    # PROGRAMMING (40)
    a("programming","Big-O Notation","Complejidad temporal y espacial de algoritmos.","Big-O describe cómo crece el tiempo/espacio de un algoritmo. O(1) constante, O(log n) logarítmico, O(n) lineal, O(n log n) log-lineal, O(n²) cuadrático, O(2ⁿ) exponencial.","# O(1)\ndef O_1(arr): return arr[0]\n# O(n)\nfor x in arr: pass\n# O(n²)\nfor i in arr:\n    for j in arr: pass",["Comparar algoritmos","Optimizar código"],2,"","¿Cuál es la complejidad de binary search?","O(log n). En cada paso se descarta la mitad.")
    a("programming","Recursión vs Iteración","Funciones recursivas vs bucles.","Recursión resuelve subproblemas más pequeños. Iteración usa bucles. Recursión es más elegante pero puede causar stack overflow.","def factorial(n):\n    if n <= 1: return 1\n    return n * factorial(n - 1)\ndef factorial_iter(n):\n    r = 1\n    for i in range(2, n+1): r *= i\n    return r",["Árboles","Divide y vencerás"],2,"","¿Cuándo usar recursión?","Cuando el problema tiene subestructura recursiva natural (árboles, grafos).")
    a("programming","Complejidad Espacial","Memoria extra que usa un algoritmo.","O(1) espacial significa uso constante de memoria extra (in-place).","def reverse_inplace(arr):\n    i, j = 0, len(arr)-1\n    while i < j:\n        arr[i], arr[j] = arr[j], arr[i]\n        i += 1; j -= 1",["Memoria limitada","In-place"],2,"","¿Invertir array sin memoria extra?","Dos punteros intercambiando. O(1) espacio.")
    a("programming","Stack Overflow","Error por demasiadas recursiones.","Cada llamada usa un frame. Recursión profunda desborda la pila.","def deep(n):\n    if n == 0: return\n    deep(n - 1)  # Python ~1000",["Debugging"],1,"","¿Cómo evitar stack overflow?","Convertir a iteración o tail recursion.")
    a("programming","Memoización","Caching de resultados para evitar recálculos.","Guarda resultado de función determinista. Transforma O(2^n) en O(n).","def fib_memo(n, m={}):\n    if n in m: return m[n]\n    if n <= 1: return n\n    m[n] = fib_memo(n-1,m)+fib_memo(n-2,m)\n    return m[n]",["DP","Caching"],2,"python","¿Memoización vs caching?","Memoización es caching automático de funciones. Caching es más general.")
    a("programming","Punteros y Referencias","Variables que almacenan direcciones de memoria.","Punteros acceso directo a memoria. Referencias aliases seguros.","int x = 10;\nint *p = &x;\nint &ref = x;",["Memoria","Estructuras"],3,"c","¿Puntero vs referencia en C++?","Puntero puede ser nulo. Referencia no, debe inicializarse.")
    a("programming","Garbage Collection","Libera memoria no referenciada automáticamente.","Reference counting + generational GC.","class Obj: pass\na = Obj()  # refcount=1\nb = a      # refcount=2\ndel b; del a  # GC libera",["Lenguajes managed"],2,"python","¿Inconvenientes del GC?","Pausas impredecibles, uso memoria adicional.")
    a("programming","Binary Search","Búsqueda que divide espacio a la mitad.","O(log n) en array ordenado.","def bs(arr, t):\n    lo, hi = 0, len(arr)-1\n    while lo <= hi:\n        m = (lo+hi)//2\n        if arr[m]==t: return m\n        elif arr[m]<t: lo=m+1\n        else: hi=m-1\n    return -1",["Búsqueda","Optimización"],2,"python","¿Qué pasa si no está ordenado?","Resultado incorrecto por descartar mitades erróneamente.")
    a("programming","Merge Sort","Divide y vencerás O(n log n) garantizado.","Es estable, O(n) espacio extra.","def ms(arr):\n    if len(arr)<=1: return arr\n    m = len(arr)//2\n    return merge(ms(arr[:m]),ms(arr[m:]))",["Ordenamiento"],2,"python","¿Merge sort vs quicksort?","Merge estable O(n) espacio. Quick in-place pero O(n²) peor caso.")
    a("programming","Hash Tables","Mapea claves a valores usando función hash.","Acceso O(1) promedio.","class HT:\n    def __init__(s,sz=100): s.t=[[] for _ in range(sz)]\n    def put(s,k,v):\n        i=hash(k)%len(s.t)\n        for j,(x,y) in enumerate(s.t[i]):\n            if x==k: s.t[i][j]=(k,v);return\n        s.t[i].append((k,v))",["Dictionaries","Caching"],2,"python","¿Peor caso hash table?","O(n) por colisiones. Mitigar con buena hash y load factor bajo.")
    a("programming","Tree Traversal","In-order, pre-order, post-order.","In-order ordena BST. Pre-order prefiere raíz.","def inorder(r):\n    if not r: return []\n    return inorder(r.left)+[r.val]+inorder(r.right)",["BST","Serialización"],2,"python","¿Qué recorrido ordena BST?","In-order: izquierda → raíz → derecha.")
    a("programming","Graph BFS/DFS","Amplitud y profundidad para grafos.","BFS cola nivel por nivel. DFS pila lo más profundo.","from collections import deque\ndef bfs(g,s):\n    v,q=set([s]),deque([s])\n    while q:\n        n=q.popleft()\n        for nb in g[n]:\n            if nb not in v: v.add(nb);q.append(nb)",["Caminos cortos","Ciclos"],2,"python","¿BFS vs DFS?","BFS caminos cortos. DFS explorar todo, backtracking.")
    a("programming","Dijkstra's Algorithm","Caminos más cortos ponderados positivos.","Cola de prioridad. No pesos negativos.","import heapq\ndef dijk(g,s):\n    d={n:float('inf')for n in g};d[s]=0\n    pq=[(0,s)]\n    while pq:\n        dd,u=heapq.heappop(pq)\n        if dd>d[u]:continue\n        for v,w in g[u]:\n            if d[u]+w<d[v]:\n                d[v]=d[u]+w;heapq.heappush(pq,(d[v],v))\n    return d",["GPS","Routing"],3,"python","¿Por qué no pesos negativos?","Asume distancia final una vez procesado.")
    a("programming","Dynamic Programming","Subproblemas superpuestos + subestructura óptima.","Memoización (top-down) o tabulación (bottom-up).","def fib(n):\n    if n<=1: return n\n    dp=[0]*(n+1);dp[1]=1\n    for i in range(2,n+1): dp[i]=dp[i-1]+dp[i-2]\n    return dp[n]",["Optimización"],3,"python","¿Cómo identificar DP?","Subestructura óptima + subproblemas superpuestos.")
    a("programming","Greedy Algorithms","Mejor decisión local esperando óptimo global.","No siempre da óptimo global.","def change(coins,amt):\n    coins.sort(reverse=True);r=[]\n    for c in coins:\n        while amt>=c: amt-=c;r.append(c)\n    return r if amt==0 else None",["Selección","Huffman"],2,"python","¿Cuándo greedy NO da óptimo?","Sin subestructura greedy, como mochila 0/1.")
    a("programming","Backtracking","Fuerza braza que retrocede cuando falla.","Explora todas soluciones, descarta no válidas.","def subsets(nums):\n    r=[]\n    def bt(s,c):\n        r.append(c[:])\n        for i in range(s,len(nums)):\n            c.append(nums[i]);bt(i+1,c);c.pop()\n    bt(0,[]);return r",["Permutación","Sudoku"],3,"python","¿Complejidad para subconjuntos?","O(2^n). Cada elemento incluido o no.")
    a("programming","Sliding Window","Ventana móvil para problemas de subarray.","Ajusta ventana incrementalmente.","def max_sub(arr,k):\n    ml=ws=l=0\n    for r in range(len(arr)):\n        ws+=arr[r]\n        while ws>k: ws-=arr[l];l+=1\n        ml=max(ml,r-l+1)\n    return ml",["Subarray","Substring"],2,"python","¿Cómo decidir sliding window?","Cuando ventana se ajusta incrementalmente.")
    a("programming","Two Pointers","Dos índices moviéndose en direcciones específicas.","Reduce O(n²) a O(n).","def two_sum(arr,t):\n    l,r=0,len(arr)-1\n    while l<r:\n        s=arr[l]+arr[r]\n        if s==t: return [l,r]\n        elif s<t: l+=1\n        else: r-=1\n    return [-1,-1]",["Arrays ordenados","Palindrome"],2,"python","¿Two pointers vs brute?","Cuando array ordenado o reducible de O(n²) a O(n).")
    a("programming","Linked Lists","Estructura lineal nodos enlazados.","Inserciones/eliminaciones O(1).","class LN:\n    def __init__(s,v=0,n=None):s.v=v;s.n=n\ndef rev(h):\n    p,c=None,h\n    while c:\n        nx=c.n;c.n=p;p=c;c=nx\n    return p",["Pilas/colas"],2,"python","¿Ventaja sobre array?","Inserciones O(1) sin desplazar.")
    a("programming","Stacks and Queues","LIFO pila y FIFO cola.","Stack backtrack. Cola BFS.","class Stack:\n    def __init__(s):s.i=[]\n    def push(s,x):s.i.append(x)\n    def pop(s):return s.i.pop()",["Parsing","BFS","Undo"],1,"python","¿Cola con dos stacks?","Uno enqueue, otro dequeue. Vaciar entrada en salida.")
    a("programming","Heap","Árbol padre menor/mayor que hijos.","Acceso O(1) mínimo/máximo, inserción O(log n).","import heapq\nclass MF:\n    def __init__(s):s.lo=[];s.hi=[]\n    def add(s,n):\n        heapq.heappush(s.lo,-n)\n        heapq.heappush(s.hi,-heapq.heappop(s.lo))\n        if len(s.hi)>len(s.lo):\n            heapq.heappush(s.lo,-heapq.heappop(s.hi))",["Median","Top K"],3,"python","¿Mediana de stream en tiempo real?","Dos heaps: max-heap inferior, min-heap superior.")
    a("programming","Trie","Árbol para almacenar strings por carácter.","Búsqueda O(m). Autocompletado.","class TN:\n    def __init__(s):s.c={};s.e=False\nclass Trie:\n    def __init__(s):s.r=TN()\n    def ins(s,w):\n        n=s.r\n        for c in w:\n            if c not in n.c:n.c[c]=TN()\n            n=n.c[c]\n        n.e=True",["Autocompletado","Prefijos"],3,"python","¿Trie vs hash table?","Trie para prefijos. Hash para búsqueda exacta.")
    a("programming","Union-Find","Conjuntos disjuntos casi O(1).","Path compression + union by rank.","class UF:\n    def __init__(s,n):s.p=list(range(n));s.r=[0]*n\n    def find(s,x):\n        if s.p[x]!=x:s.p[x]=s.find(s.p[x])\n        return s.p[x]\n    def union(s,x,y):\n        rx,ry=s.find(x),s.find(y)\n        if rx==ry:return False\n        if s.r[rx]<s.r[ry]:rx,ry=ry,rx\n        s.p[ry]=rx\n        if s.r[rx]==s.r[ry]:s.r[rx]+=1\n        return True",["Componentes","MST"],3,"python","¿Qué hace casi O(1)?","Path compression + union by rank.")
    a("programming","Topological Sort","Orden lineal en DAG.","Para dependencias y build systems.","from collections import deque\ndef ts(g,ind):\n    q=deque([n for n in g if ind[n]==0]);o=[]\n    while q:\n        n=q.popleft();o.append(n)\n        for nb in g[n]:\n            ind[nb]-=1\n            if ind[nb]==0:q.append(nb)\n    return o if len(o)==len(g) else []",["Build systems","Planificación"],2,"python","¿Detectar ciclo?","Resultado incompleto = ciclo.")
    a("programming","Bit Manipulation","Operaciones directas sobre bits.","& | ^ ~ << >> para soluciones eficientes.","a,b=5,3\na&b  # 1\na|b  # 7\na^b  # 6\ndef pow2(n):return n>0and(n&(n-1))==0",["Optimización","Cripto"],3,"","¿Contar bits 1?","n&(n-1) elimina bit 1, repetir hasta n=0.")
    a("programming","Closures","Funciones que capturan entorno léxico.","Recuerdan variables de scope externo.","def counter():\n    c=[0]\n    def inc():c[0]+=1;return c[0]\n    return inc\nc=counter()\nprint(c());print(c())  # 1,2",["Factories","Callbacks"],2,"python","¿Closure en JS?","Captura variables de scope. Para privacy y factories.")
    a("programming","Higher-Order Functions","Funciones que reciben o retornan otras.","map, filter, reduce.","d=list(map(lambda x:x*2,[1,2,3]))\ne=list(filter(lambda x:x%2==0,[1,2,3,4]))",["Transformation","Functional"],2,"python","¿map/filter vs comprehensions?","Comprehensions más pythonicas y rápidas.")
    a("programming","Generators","Funciones que producen valores bajo demanda.","yield produce valores uno a uno.","def fib():\n    a,b=0,1\n    while True: yield a;a,b=b,a+b\nfrom itertools import islice\nprint(list(islice(fib(),10)))",["Secuencias infinitas","Streaming"],2,"python","¿Generator vs list comprehension?","Generator para datasets grandes o infinitos.")
    a("programming","Decorators","Modifican comportamiento de funciones.","Syntactic sugar para higher-order functions.","import functools,time\ndef timer(f):\n    @functools.wraps(f)\n    def w(*a,**k):\n        t=time.time()\n        r=f(*a,**k)\n        print(f'{f.__name__} took {time.time()-t:.2f}s')\n        return r\n    return w\n@timer\ndef slow():time.sleep(1)",["Logging","Caching","Auth"],2,"python","¿Cómo funciona syntactic sugar?","@decorator def f() es f = decorator(f).")
    a("programming","Context Managers","Scope de recursos abren/cierran automáticamente.","Garantizan liberación de recursos.","class FM:\n    def __init__(s,p,m):s.p=p;s.m=m\n    def __enter__(s):s.f=open(s.p,s.m);return s.f\n    def __exit__(s,*a):s.f.close()\nwith FM('t.txt','w') as f: f.write('hi')",["Archivos","BD","Transacciones"],2,"python","¿Qué garantizan?","__exit__ se ejecuta siempre, incluso con excepción.")
    a("programming","Threading","Concurrencia de múltiples hilos.","Comparten memoria. I/O-bound.","import threading\ndef dl(url,r,i):\n    time.sleep(1);r[i]=f'DL {url}'\nr=[None]*3\nts=[threading.Thread(target=dl,args=(f'u{i}',r,i))for i in range(3)]\nfor t in ts:t.start()\nfor t in ts:t.join()",["I/O","Scraping"],2,"python","¿Threading vs multiprocessing?","Threading memoria compartida (I/O). Multiprocessing memoria separada (CPU).")
    a("programming","Async/Await","Programación asíncrona sin threads explícitos.","Event loop gestiona concurrencia.","import asyncio\nasync def f(url):\n    async with aiohttp.ClientSession() as s:\n        async with s.get(url) as r:\n            return await r.text()\nasync def main():\n    await asyncio.gather(f('u1'),f('u2'))",["APIs","Scraping"],3,"python","¿async/await vs threads?","async/await más eficiente para miles de operaciones I/O.")
    a("programming","Mutex and Locks","Protegen secciones críticas concurrentes.","Solo un thread accede a recurso compartido.","import threading\nclass C:\n    def __init__(s):s.c=0;s.l=threading.Lock()\n    def inc(s):\n        with s.l: s.c+=1",["Race conditions","Críticas"],3,"python","¿Deadlock y cómo evitar?","Threads esperando recursos de otros. Evitar: ordenar locks, timeout.")
    a("programming","Semaphore","Contador que controla concurrencia.","Permite N concurrentes en lugar de 1.","import asyncio\nsem=asyncio.Semaphore(5)\nasync def f(s,url):\n    async with sem:\n        async with s.get(url) as r: return await r.text()",["Rate limiting","Connection pool"],3,"python","¿Semaphore vs mutex?","Mutex permite 1. Semaphore permite N.")
    a("programming","Race Conditions","Resultado depende del timing de threads.","Múltiples threads acceden sin sincronización.","class BA:\n    def __init__(s,b):s.b=b\n    def bad(s,amt):\n        if s.b>=amt:s.b-=amt  # Race!\n    def good(s,amt):\n        with s.l:\n            if s.b>=amt:s.b-=amt",["Concurrencia"],3,"python","¿Detectar en producción?","ThreadSanitizer, logs inconsistentes, no determinístico.")
    a("programming","Deadlock","Threads bloqueados esperando recursos de otros.","4 condiciones: mutual exclusion, hold & wait, no preemption, circular wait.","# Prevention: always acquire in same order\nlock_a.acquire();lock_b.acquire()  # Thread A\nlock_b.acquire();lock_a.acquire()  # Thread B → deadlock",["Sistemas concurrentes"],3,"python","¿4 condiciones?","Mutual exclusion, hold & wait, no preemption, circular wait.")
    a("programming","Observer Pattern","Dependencia uno-a-muchos.","Subject notifica observadores automáticamente.","class Sub:\n    def __init__(s):s._o=[];s._st=None\n    def attach(s,o):s._o.append(o)\n    def notify(s):\n        for o in s._o: o.upd(s)\n    @property\n    def st(s):return s._st\n    @st.setter\n    def st(s,v):s._st=v;s.notify()",["Events","Reactive"],2,"python","¿Observer vs Pub/Sub?","Observer síncrono directo. Pub/Sub usa broker.")
    a("programming","Strategy Pattern","Familia de algoritmos intercambiables.","Cambia algoritmo en runtime.","class Sorter:\n    def __init__(s,strat):s.strat=strat\n    def sort(s,data):return s.strat.sort(data)",["Algorithms","Flexibility"],2,"python","¿Strategy vs herencia?","Strategy cambia en runtime. Herencia es estática.")
    a("programming","Factory Pattern","Delega creación de objetos a método especializado.","Permite crear diferentes tipos.","class AF:\n    @staticmethod\n    def create(t):\n        if t=='dog': return Dog()\n        elif t=='cat': return Cat()\n        raise ValueError(t)",["Creation","Flexibility"],2,"python","¿Factory vs Abstract Factory?","Factory crea un tipo. Abstract Factory crea familias.")
    a("programming","Singleton Pattern","Una sola instancia global.","Configuración, connection pools.","class S:\n    _i=None\n    def __new__(cls):\n        if cls._i is None:cls._i=super().__new__(cls)\n        return cls._i",["Config","Pools"],2,"python","¿Problemas del Singleton?","Dificulta testing, acoplamiento, viola SRP.")
    a("programming","Adapter Pattern","Convierte interfaz de una clase en otra.","Permite clases incompatibles trabajar juntas.","class Adapter:\n    def __init__(s,old):s.old=old\n    def convert(s):return f'Conv: {s.old.old_req()}'",["Integration","Legacy"],2,"python","¿Adapter vs Facade?","Adapter traduce. Facade simplifica.")
    a("programming","Facade Pattern","Interfaz simplificada a subsistema complejo.","Oculta complejidad.","class CompF:\n    def __init__(s):s.cpu=CPU();s.mem=Mem()\n    def start(s):s.cpu.freeze();s.mem.load();s.cpu.exec()",["Simplificación"],2,"python","¿Facade vs Adapter?","Facade crea nueva interfaz. Adapter traduce existente.")
    a("programming","Repository Pattern","Abstrae acceso a datos.","Encapsula SQL, APIs, archivos.","class UR(ABC):\n    @abstractmethod\n    def get(s,id):pass\nclass SQLUR(UR):\n    def __init__(s,db):s.db=db\n    def get(s,id):return s.db.query(id)",["Clean Arch","Testing"],2,"python","¿Repository si hay ORM?","Desacoplamiento, testing, cambiar BBDD.")
    a("programming","Dependency Injection","Objeto recibe dependencias de fuera.","Facilita testing y desacoplamiento.","class US:\n    def __init__(s,repo,email):  # Injected\n        s.repo=repo;s.email=email",["Testing","Clean Arch"],2,"python","¿DI vs IoC?","IoC es principio. DI es implementación.")
