    a("python","Decorators Avanzados","Con argumentos, de clase, stacking.","Personalización: parámetros, clases, apilados.","import functools\ndef retry(n=3):\n    def dec(f):\n        @functools.wraps(f)\n        def w(*a,**k):\n            for i in range(n):\n                try:return f(*a,**k)\n                except:\n                    if i==n-1:raise\n                    time.sleep(2**i)\n        return w\n    return dec",["Retry","Caching"],3,"python","¿Stacking?","@dec2 @dec1 f → f=dec2(dec1(f)). Abajo hacia arriba.")
