    a("python","Pattern Matching","Match/case con patrones destructivos.","Python 3.10+.","def h(cmd):\n    match cmd.split():\n        case['quit']:return 'Bye'\n        case['hi',n]:return f'Hello {n}'\n        case_:return 'Unknown'",["Pattern matching"],2,"python","¿vs if/elif?","Match/case más poderoso para deconstruir.")
    a("python","Frozen Dataclasses","Dataclasses inmutables y hashable.","frozen=True.","@dataclass(frozen=True)\nclass P:\n    x:float;y:float\np=P(1,2)\npts={p}  # Hashable!",["Immutable"],2,"python","¿vs Named Tuple?","Frozen más legible. NT más ligero.")
    a("python","Descriptor Protocol","Controlar acceso a atributos.","__get__, __set__ para lógica personalizada.","class Pos:\n    def __set_name__(s,o,n):s.n=n\n    def __get__(s,o,t=None):return getattr(o,f'_{s.n}',0)\n    def __set__(s,o,v):\n        if v<=0:raise ValueError()\n        setattr(o,f'_{s.n}',v)",["ORMs","Properties"],3,"python","¿Descriptor vs property?","Property es syntactic sugar para descriptor.")
    a("python","Memory Views","Vistas de memoria zero-copy.","Acceso a buffers sin copiar.","data=bytearray(b'Hello')\nv=memoryview(data)\nchunk=v[0:5]  # Sin copia!\nprint(chunk.tobytes())",["Zero-copy"],3,"python","¿vs slicing?","memoryview no copia. Slicing crea copia.")
    a("python","__init_subclass__","Hook al heredar una clase.","Auto-registro de subclases.","class Plg:\n    _r={}\n    def __init_subclass__(cls,**k):\n        super().__init_subclass__(**k)\n        Plg._r[cls.__name__]=cls\nclass AP(Plg):pass\nclass VP(Plg):pass",["Plugins","Registration"],3,"python","¿vs metaclass?","__init_subclass__ más simple para auto-registro.")
    a("python","PEP 695 Type Syntax","Nueva sintaxis generics Python 3.12+.","type[T] y def f[T]().","def first[T](items:list[T])->T:\n    return items[0]\ntype Point=tuple[float,float]",["Modern Python"],2,"python","¿vs TypeVar?","Más concisa. TypeVar para constraints.")
    a("python","Async Generators","Generadores con async/yield.","Valores lazy de forma asíncrona.","async def fetch(urls):\n    for u in urls:\n        async with aiohttp.ClientSession() as s:\n            async with s.get(u) as r:\n                yield await r.text()",["Streaming","APIs"],3,"python","¿vs async iterator?","Generator es syntactic sugar, más conciso.")
    a("python","Generators as Decorators","Generators dentro de decorators.","Estado con yield.","import functools\ndef calls(f):\n    @functools.wraps(f)\n    def w(*a,**k):\n        w.c+=1;print(f'Call #{w.c}')\n        return f(*a,**k)\n    w.c=0\n    return w",["State","Counters"],2,"python","¿Estado en decorator?","Closure con lista mutable o atributo.")
    a("python","Async Iterators","Iteradores con async/await.","Para secuencias que requieren E/S.","class AC:\n    def __init__(s,n):s.n=n;s.c=0\n    def __aiter__(s):return s\n    async def __anext__(s):\n        if s.c>=s.n:raise StopAsyncIteration\n        await asyncio.sleep(.1);s.c+=1;return s.c",["Async streams"],3,"python","¿vs sync iterator?","Async para cuando obtener siguiente valor requiere E/S.")
    a("python","__slots__ Performance","Mejorar rendimiento con __slots__.","Elimina __dict__, acceso más rápido.","import sys\nclass D:\n    def __init__(s,x,y):s.x=x;s.y=y\nclass S:\n    __slots__=['x','y']\n    def __init__(s,x,y):s.x=x;s.y=y\nprint(sys.getsizeof(D(1,2)))  # ~200+\nprint(sys.getsizeof(S(1,2)))  # ~40",["Performance"],2,"python","¿Trade-offs?","No __dict__, no herencia múltiple slots, sin atributos dinámicos.")
    a("python","Type Narrowing","Reducir tipos después de checks.","isinstance permite inferir tipos.","def p(v:Union[int,str])->str:\n    if isinstance(v,int):return str(v*2)\n    else:return v.upper()",["Type safety"],3,"python","¿Type narrowing?","isinstance permite al type checker inferir tipo específico.")

    # JAVASCRIPT (25)
    a("javascript","Event Loop","Mecanismo asíncrono en JS de un solo hilo.","Microtasks (Promises) prioritario sobre macrotasks.","console.log('1')\nsetTimeout(()=>console.log('2'),0)\nPromise.resolve().then(()=>console.log('3'))\nconsole.log('4')\n// 1,4,3,2",["Understanding async"],3,"javascript","¿Microtask vs macrotask?","Microtasks antes del siguiente macrotask.")
    a("javascript","Closures","Funciones que recuerdan scope léxico.","Capturan variables de scope externo.","function counter(){\n    let c=0\n    return()=>{c++;return c}\n}\nconst cnt=counter()\ncnt();cnt()  // 1,2",["Privacy","Factories"],2,"javascript","¿Variables privadas sin #?","Closures: variables en scope inaccesibles desde fuera.")
    a("javascript","Promises","Resultado futuro de operación asíncrona.","pending→fulfilled/rejected.","const f=()=>new Promise((res,rej)=>{\n    setTimeout(()=>res('data'),1000)\n})\nf().then(d=>console.log(d))\nPromise.all([f1,f2]).then(([a,b])=>console.log(a,b))",["Async","API calls"],2,"javascript","¿Promise.all vs allSettled?","all falla si una rechaza. allSettled espera todos.")
    a("javascript","Async/Await","Syntactic sugar para Promises.","Código asíncrono parecer síncrono.","async function getUser(id){\n    try{\n        const r=await fetch(`/api/u/${id}`)\n        return await r.json()\n    }catch(e){console.error(e)}\n}",["Async","Error handling"],2,"javascript","¿vs .then()?","async/await más legible, facilita debugging.")
    a("javascript","Destructuring","Extraer valores de arrays/objetos.","Extrae en variables individuales.","const{name,age,...r}={name:'John',age:30,city:'NYC'}\nconst[fr,...others]=[1,2,3,4]",["ES6+","Concise"],1,"javascript","¿vs accessor?","Destructuring más conciso. Accessor más explícito.")
    a("javascript","Spread/Rest","Operador ... expandir o recoger.","Spread expande. Rest recoge.","const a2=[...[1,2],3,4]\nconst o2={...{a:1},c:3}\nfunction sum(...n){return n.reduce((a,b)=>a+b,0)}",["ES6+","Immutable"],1,"javascript","¿vs concat?","Spread más rápido, mezcla tipos.")
    a("javascript","ES6 Modules","Sistema de módulos nativo.","import/export, tree shaking.","export const PI=3.14\nexport default class Calc{...}\nimport Calc,{PI}from'./utils.js'",["Code organization"],2,"javascript","¿vs CommonJS?","ES6 estático, tree-shaking. CommonJS runtime, legacy.")
    a("javascript","Map/Set/WeakMap","Estructuras de datos ES6.","Map claves cualquier tipo. Set valores únicos.","const m=new Map()\nm.set('k','v');m.set(42,'n')\nconst s=new Set([1,2,3,2])\ns.size  // 3",["Data structures"],2,"javascript","¿Map vs plain object?","Map acepta cualquier clave, tiene size, preserva orden.")
    a("javascript","Iterators/Generators","Protocolo de iteración y funciones lazy.","Generators con yield implementan Iterator.","function* fib(){\n    let[a,b]=[0,1]\n    while(true){yield a;[a,b]=[b,a+b]}\n}\nconst f=fib();f.next().value  // 0",["Lazy","Infinite"],2,"javascript","¿Generator vs Promise?","Generator produce valores secuencialmente. Promise un valor futuro.")
    a("javascript","Proxy/Reflect","Interceptar operaciones en objetos.","Interceptan get, set, delete, etc.","const v={\n    set(t,p,v){\n        if(p==='age'&&typeof v!=='number')throw TypeError()\n        return Reflect.set(t,p,v)\n    }\n}\nconst p=new Proxy({},v)",["Meta-programming","Validation"],3,"javascript","¿vs defineProperty?","Proxy intercepta cualquier operación. defineProperty solo get/set.")
    a("javascript","Optional Chaining (?.)","Acceso seguro a propiedades anidadas.","?. retorna undefined en lugar de error.","const s=u?.a?.s\nconst n=u?.getName?.()\nconst f=a?.[0]",["Null safety","ES2020"],1,"javascript","¿vs && chains?","?. más conciso, maneja null/undefined, funciona con métodos.")
    a("javascript","Nullish Coalescing (??)","Retorna derecho solo si izquierdo null/undefined.","?? solo actúa con null/undefined.","const p=c.p??3000  // 0 si es 0\nconst h=c.h??'localhost'",["Default values","ES2020"],1,"javascript","¿?? vs ||?","|| para cualquier falsy. ?? solo null/undefined.")
    a("javascript","Promise combinators","all, allSettled, race, any.","Cada uno con caso de uso diferente.","await Promise.all([p1,p2,p3])\nawait Promise.allSettled([p1,p2,p3])\nawait Promise.race([p1,p2,p3])\nawait Promise.any([p1,p2,p3])",["Async patterns"],2,"javascript","¿all vs allSettled?","all falla rápido. allSettled espera todos.")
    a("javascript","Temporal API","Fechas/horas inmutables modernas.","Reemplaza Date, maneja timezones.","const now=Temporal.Now.zonedDateTimeISO()\nconst d=Temporal.PlainDate.from('2024-01-15')\nconst nw=now.add({days:7})",["Date handling"],2,"javascript","¿vs Date?","Temporal inmutable, más tipos, timezones correctas.")
    a("javascript","Record and Tuple","Tipos inmutables propuestos.","Comparados por valor.","const p=#{x:1,y:2}\nconst c=#[1,2,3]\nconst a=#{x:1};const b=#{x:1}\na===b  // true (valor)",["Immutability"],3,"javascript","¿vs Object/Array?","Record/Tuple inmutables y comparados por valor.")
    a("javascript","Decorators (TC39)","Modificar clases/métodos declarativamente.","Stage 3 propuesto.","function log(v,{kind,name}){\n    if(kind==='method')return function(...a){\n        console.log(`Call ${name}`);return v.call(this,...a)\n    }\n}\nclass C{@log m(){}}",["Meta-programming"],3,"javascript","¿vs提案?","Stage 3 más estable, más simples.")
    a("javascript","using keyword","Gestión automática de recursos.","Libera automáticamente al salir scope.","function rf(p){\n    const f=open(p)\n    return{[Symbol.dispose]:()=>f.close()}\n}\n{using f=rf('t.txt');console.log(f.read())}",["Resource management"],2,"javascript","¿vs try/finally?","using más conciso y automático.")
    a("javascript","Promise.try","Manejar errores síncronos en contexto async.","Encapsula excepciones síncronas.","const r=await Promise.try(()=>{\n    if(!u)throw Error('No user')\n    return proc(u)\n}).catch(handler)",["Error handling"],2,"javascript","¿vs new Promise?","Más conciso para funciones síncronas.")
    a("javascript","Object.groupBy","Agrupar arrays declarativamente.","Object.groupBy y Map.groupBy.","const p=[{n:'A',a:25},{n:'B',a:30}]\nconst by=Object.groupBy(p,x=>x.a)",["Data transformation","ES2024"],1,"javascript","¿vs reduce?","groupBy más declarativo. reduce más flexible.")
    a("javascript","Promise.withResolvers","Crear Promise con resolve/reject expuestos.","Control externo de la promise.","const{promise,resolve,reject}=Promise.withResolvers()\nbutton.onclick=()=>resolve('clicked')\nconst r=await promise",["Promise patterns"],2,"javascript","¿vs new Promise?","Más limpio cuando resolve/reject en scope diferente.")
    a("javascript","Array.at()","Acceso por índice con negativos.","arr.at(-1) retorna último elemento.","const a=[1,2,3]\na.at(-1)  // 3\na.at(-2)  // 2",["Array methods","ES2022"],1,"javascript","¿at() vs [length-1]?","at() es más conciso y legible.")
    a("javascript","Structured Clone","Copia profunda de objetos nativa.","Reemplaza JSON.parse(JSON.stringify()).","const original={a:1,b:{c:2}}\nconst clone=structuredClone(original)\nclone.b.c=99\noriginal.b.c  // 2 (no afectado)",["Deep copy","ES2022"],1,"javascript","¿vs JSON clone?","structuredClone maneja Date, Map, Set, circular references.")
    a("javascript","Error Cause","Causa de errores encadenados.","new Error('msg',{cause:originalError}).","try{\n    parse()\n}catch(e){\n    throw new Error('Parse failed',{cause:e})\n}",["Error handling","ES2022"],1,"javascript","¿Por qué cause?","Preserva el error original para debugging.")
    a("javascript","Top-level await","await fuera de async functions.","ES2022 permite await en modules.","// module.js\nconst data=await fetch('/api/data').then(r=>r.json())\nexport{data}",["Modules","ES2022"],1,"javascript","¿Top-level await?","Evita IIFE async o async wrappers en modules.")

    # LINUX/DEVOPS/DOCKER/K8S (50)
    a("linux","File System Hierarchy","/bin /etc /var /home estándar.","FHS: /bin binarios, /etc config, /var datos, /home users.","ls /bin /etc /var/log /home /tmp",["Admin","Debugging"],1,"bash","¿/bin vs /usr/bin?","/bin esenciales boot. /usr/bin usuario. Modernamente symlink.")
    a("linux","Process States","Running, Sleeping, Stopped, Zombie.","R=running, S=sleeping, D=disk, T=stopped, Z=zombie.","ps aux\n# R S D T Z",["Debugging"],2,"bash","¿Zombie y cómo eliminarlo?","Terminado cuyo padre no hizo wait(). SIGCHLD.")
    a("linux","Signals","Mensajes para controlar procesos.","SIGTERM pide, SIGKILL fuerza, SIGHUP recarga.","kill -SIGTERM 1234\nkill -SIGKILL 1234\nkill -SIGHUP 1234",["Control","Scripts"],2,"bash","¿SIGTERM vs SIGKILL?","SIGTERM permite limpieza. SIGKILL fuerza sin limpieza.")
    a("linux","Crontab","Tareas periódicas.","minuto hora día mes día_semana comando.","0 1 * * * /backup.sh\ncrontab -e\n0 0 * * 0 /weekly.sh",["Tareas","Automatización"],1,"bash","¿Evitar emails cron?","'>/dev/null 2>&1' o MAILTO vacío.")
    a("linux","Systemd Services","Gestión de servicios moderna.","Unit files con start, stop, enable, logs.","sudo systemctl enable mysvc\nsudo systemctl start mysvc\nsudo journalctl -u mysvc -f",["Gestión"],2,"bash","¿vs init.d?","Systemd paralelo, más rápido. init.d legacy.")
    a("linux","Permissions","Owner, group, others rwx.","chmod, chown, chgrp. 755, u+x.","chmod 755 file\nchmod u+x file\nchown user:group file",["Security"],1,"bash","¿Setuid?","Ejecuta con permisos del owner.")
    a("linux","Disk Management","fdisk, mount, LVM, RAID.","Particionar, montar, volúmenes flexibles.","sudo fdisk /dev/sdb\nsudo mkfs.ext4 /dev/sdb1\nsudo mount /dev/sdb1 /mnt",["Storage"],2,"bash","¿LVM vs particiones?","LVM redimensiona sin downtime.")
    a("linux","Networking Commands","ip, ss, curl, dig, ping.","ip configura, ss sockets, curl HTTP.","ip addr show\nss -tulnp\ncurl -I https://example.com",["Troubleshooting"],1,"bash","¿ss vs netstat?","ss más rápido, reemplazo moderno.")
    a("linux","Log Management","journald, rsyslog, logrotate.","journald systemd. rsyslog centralizado.","journalctl -u nginx -f\njournalctl --since today",["Observability"],2,"bash","¿journald vs syslog?","journald binario, indexado. syslog texto, legacy.")
    a("linux","Process Management","ps, top, htop, nice, kill.","Monitorean, prioridad, jobs.","ps aux --sort=-%mem | head\ntop -bn1\nnice -n 10 ./heavy.sh",["Performance"],2,"bash","¿nice vs renice?","nice al inicio. renice durante ejecución.")
    a("linux","SSH Tunneling","Túneles SSH para redirigir tráfico.","Local, remoto, dinámico SOCKS.","ssh -L 5432:db:5432 user@jump\nssh -R 3000:localhost:3000 user@srv\nssh -D 1080 user@srv",["Security","Networking"],3,"bash","¿vs VPN?","SSH simple punto a punto. VPN más completo.")
    a("linux","Firewall Management","iptables, nftables, ufw.","ufw simplificado. nftables moderno.","sudo ufw enable\nsudo ufw allow 22/tcp\nsudo ufw allow 80/tcp",["Security"],2,"bash","¿iptables vs nftables vs ufw?","ufw simple. iptables flexible. nftables reemplazo moderno.")
    a("docker","Docker Networking","bridge, host, overlay, none.","Bridge default. Host sin aislamiento. Overlay multi-host.","docker network create --driver bridge mynet\ndocker run --network mynet web nginx",["Microservicios"],2,"bash","¿Overlay vs bridge?","Overlay para comunicación multi-host.")
    a("docker","Build Cache","Cachea capas para builds rápidos.","Orden de instrucciones afecta cache.","FROM node:20-alpine\nCOPY package*.json ./\nRUN npm ci --production\nCOPY . .",["CI/CD","Optimization"],2,"bash","¿Por qué copiar package.json primero?","Aprovechar cache de dependencias.")
    a("docker","Multi-stage Builds","Imágenes pequeñas con múltiples etapas.","Compilar etapa, copiar artifacts finales.","FROM golang:1.21 AS b\nCOPY . .\nRUN go build -o srv\nFROM alpine:3.18\nCOPY --from=b /app/srv ./\n# ~15MB vs ~800MB",["Producción"],3,"bash","¿Ventajas?","Imágenes más pequeñas, mejor seguridad.")
    a("docker","Docker Security","No-root, imágenes mínimas, secrets.","Escaneo vulnerabilidades.","FROM node:20-alpine\nRUN adduser -S appuser\nUSER appuser",["Security"],2,"bash","¿No root?","Root puede escapar y comprometer host.")
    a("docker","Docker Compose","Multi-container applications.","Define servicios, redes, volúmenes.","services:\n  web:\n    build: .\n    ports: ['3000:3000']\n  db:\n    image: postgres:15",["Local dev"],1,"bash","¿vs Swarm?","Compose un host, desarrollo. Swarm producción multi-host.")
    a("kubernetes","Pods","Unidad mínima desplegable.","Contenedores comparten red, volumen.","apiVersion: v1\nkind: Pod\nspec:\n  containers:\n  - name: app\n    image: nginx:1.25",["Despliegue"],2,"yaml","¿Multi-container?","Sidecar (logging, proxy) comparten red y volumen.")
    a("kubernetes","Services","Expone Pods como servicio de red.","IP estable y load balancing.","apiVersion: v1\nkind: Service\nspec:\n  type: ClusterIP\n  selector:\n    app: my-app\n  ports:\n  - port: 80",["Discovery"],2,"yaml","¿ClusterIP vs NodePort vs LoadBalancer?","ClusterIP interno. NodePort nodo. LoadBalancer externo.")
    a("kubernetes","Deployments","Controller para réplicas y rolling updates.","Réplicas,滚动更新, rollback.","apiVersion: apps/v1\nkind: Deployment\nspec:\n  replicas: 3\n  strategy:\n    type: RollingUpdate\n    rollingUpdate:\n      maxSurge: 1\n      maxUnavailable: 0",["Zero-downtime"],2,"yaml","¿maxSurge vs maxUnavailable?","maxSurge: pods extra. maxUnavailable: indisponibles.")
    a("kubernetes","ConfigMaps y Secrets","Configuración y datos sensibles.","ConfigMaps no sensible. Secrets sensibles (base64).","apiVersion: v1\nkind: ConfigMap\ndata:\n  DB_URL: postgres://db:5432/mydb",["Configuration"],2,"yaml","¿ConfigMap vs Secret?","ConfigMap valores no sensibles. Secret passwords/tokens.")
    a("kubernetes","Ingress","Acceso HTTP externo a servicios.","Reglas routing HTTP por hostname/path.","apiVersion: networking.k8s.io/v1\nkind: Ingress\nspec:\n  rules:\n  - host: myapp.com\n    http:\n      paths:\n      - path: /api",["HTTP routing"],2,"yaml","¿vs LoadBalancer?","Ingress routing HTTP. LoadBalancer exposición simple.")
    a("kubernetes","PersistentVolumes","Almacenamiento persistente.","PV recurso. PVC solicitud.","apiVersion: v1\nkind: PersistentVolumeClaim\nspec:\n  resources:\n    requests:\n      storage: 10Gi",["Persistence"],2,"yaml","¿PVC vs emptyDir?","PVC persiste. emptyDir se destruye con Pod.")
    a("devops","CI/CD Pipeline","Integración y despliegue continuo.","CI: build, test. CD: deploy.","name: CI\non: [push]\njobs:\n  build:\n    steps:\n      - run: npm ci\n      - run: npm test",["Automation"],2,"yaml","¿CI vs CD?","CI integración continua. CD despliegue continuo.")
    a("devops","Infrastructure as Code","Infraestructura gestionada mediante código.","Terraform, Pulumi, CloudFormation.","resource 'aws_instance' 'web' {\n  ami = 'ami-xxx'\n  instance_type = 't3.micro'\n}",["Reproducibility"],2,"hcl","¿Terraform vs Pulumi?","Terraform HCL. Pulumi lenguajes reales.")
    a("devops","Monitoring","Métricas, logs, trazas.","Los tres pilares de observabilidad.","groups:\n- name: alerts\n  rules:\n  - alert: HighCPU\n    expr: 100-(avg(rate(cpu[5m]))*100)>80",["Observability"],2,"yaml","¿Métricas, logs, trazas?","Métricas: qué. Logs: por qué. Trazas: dónde.")
    a("devops","GitOps","Git como fuente de verdad.","ArgoCD/Flux sincronizan automáticamente.","apiVersion: argoproj.io/v1alpha1\nkind: Application\nspec:\n  source:\n    repoURL: https://github.com/org/k8s",["GitOps"],2,"yaml","¿vs CI/CD tradicional?","GitOps: Git fuente, reconciliación automática.")
    a("devops","Secrets Management","Gestión segura de secretos.","Vault, AWS SM, K8s Secrets.","vault kv put secret/myapp/db pw='x'\nkubectl create secret generic db --from-literal=pw=x",["Security"],2,"bash","¿Vault vs K8s Secrets?","Vault: auditing, rotación. K8s: simple, base64.")
    a("devops","Blue-Green Deployment","Dos entornos, cambio instantáneo.","Rollback instantáneo.","upstream blue{server 10.0.0.1:8080;}\nupstream green{server 10.0.0.2:8080;}",["Zero-downtime"],2,"bash","¿vs canary?","Blue-green: cambio instantáneo. Canary: gradual.")
    a("devops","Canary Deployment","Despliegue gradual con porción de tráfico.","1-5% tráfico nueva versión.","split_clients '${remote_addr}' $up {\n    5% canary;\n    * stable;\n}",["Gradual rollout"],3,"bash","¿vs A/B testing?","Canary probar nueva versión. A/B comparar variantes.")
    a("devops","Feature Flags","Habilitar features sin deploy.","Activar gradualmente, rollback.","import os\ndef is_on(f):return os.getenv(f'FF_{f}','false')=='true'\nif is_on('NEW'):return new_flow()",["Feature management"],2,"python","¿vs deploy?","Flags activar sin deploy. Deploy cada cambio requiere deploy.")
    a("devops","Monitoring Stack","Prometheus + Grafana + AlertManager.","Prometheus recolecta, Grafana visualiza.","scrape_configs:\n  - job_name: 'node'\n    static_configs:\n      - targets: ['localhost:9100']",["Metrics"],2,"yaml","¿Prometheus vs Datadog?","Prometheus open-source. Datadog SaaS más features.")

    # DATABASES (25)
    a("postgresql","Indexes","Estructuras que aceleran consultas.","B-tree, GIN, GiST, BRIN.","CREATE INDEX idx ON users(email);\nCREATE INDEX idx ON t USING GIN(col);",["Query optimization"],2,"sql","¿Cuándo NO índice?","Tablas pequeñas, baja selectividad, muchas escrituras.")
    a("postgresql","MVCC","Multi-Version Concurrency Control.","Versiones por transacción.","BEGIN;\nSET ISOLATION LEVEL READ COMMITTED;\nSELECT * FROM accounts WHERE id=1;",["Concurrencia"],3,"sql","¿Vacuum?","Elimina tuples muertas de MVCC. autovacuum automático.")
    a("postgresql","CTEs","Common Table Expressions.","Simplifican consultas, recursion.","WITH RECURSIVE tree AS(\n    SELECT id,name,1 as lvl FROM emp WHERE mgr IS NULL\n    UNION ALL\n    SELECT e.id,e.name,t.lvl+1\n    FROM emp e JOIN tree t ON e.mgr=t.id\n)",["Reporting","Recursive"],2,"sql","¿vs subquery?","CTEs más legibles, reutilizables, recursion.")
    a("postgresql","Window Functions","Funciones sobre conjunto de filas relacionadas.","ROW_NUMBER, RANK, LAG, LEAD.","SELECT name,salary,\n    ROW_NUMBER() OVER(PARTITION BY dept ORDER BY salary DESC) as rank\nFROM emp;",["Analytics"],2,"sql","¿vs GROUP BY?","Window mantiene filas. GROUP BY agrega.")
    a("postgresql","JSONB","Tipo binario para JSON eficientemente.","Índices y consultas sobre JSON.","CREATE TABLE events(id SERIAL PRIMARY KEY,data JSONB);\nSELECT * FROM events WHERE data->>'type'='click';\nCREATE INDEX ON events USING GIN(data);",["Flexible schemas"],2,"sql","¿JSONB vs JSON?","JSONB binario, indexable. JSON texto plano.")
    a("mongodb","Document Model","Documentos BSON jerárquivos.","Schemas flexibles.","db.users.insertOne({name:'John',age:30,address:{city:'NYC'}})\ndb.users.find({'address.city':'NYC'})",["Document DB"],2,"javascript","¿vs PostgreSQL?","MongoDB flexibilidad. PostgreSQL relaciones y ACID.")
    a("redis","Data Structures","Strings, Lists, Sets, Hashes, Sorted Sets.","Operaciones atómicas.","SET user:1 name 'John'\nLPUSH q 'task1'\nSADD tags 'python'\nHSET u:1 name 'John' age 30\nZADD lb 100 'p1'",["Caching","Real-time"],2,"bash","¿Sorted Set vs Hash?","Sorted Set ranking. Hash objetos.")
    a("redis","Persistence","RDB snapshots y AOF.","RDB periódicos. AOF cada operación.","save 900 1\nappendonly yes\nBGSAVE",["Durability"],2,"bash","¿RDB vs AOF?","RDB snapshots rápidos. AOF más durabilidad.")
    a("redis","Pub/Sub","Mensajería publish/subscribe.","No persiste si no hay subscribers.","SUBSCRIBE ch1\nPUBLISH ch1 'Hello!'",["Real-time"],2,"bash","¿vs Streams?","Pub/Sub fire-and-forget. Streams persiste.")
    a("mysql","Query Optimization","Mejorar rendimiento SQL.","EXPLAIN, índices, denormalización.","EXPLAIN SELECT * FROM users WHERE email='x';\nCREATE INDEX idx ON users(email);",["Performance"],2,"sql","¿EXPLAIN?","Muestra plan: tipo acceso, keys, rows.")
    a("databases","ACID Properties","Atomicidad, Consistencia, Aislamiento, Durabilidad.","Propiedades de transacciones.","BEGIN;\nUPDATE accounts SET bal=bal-100 WHERE id=1;\nUPDATE accounts SET bal=bal+100 WHERE id=2;\nCOMMIT;",["Transacciones"],2,"sql","¿ACID vs BASE?","ACID consistencia fuerte. BASE disponibilidad (NoSQL).")
    a("databases","CAP Theorem","Consistency, Availability, Partition tolerance: solo 2 de 3.","CP: MongoDB. AP: Cassandra. CA: PostgreSQL.","CP: MongoDB (consistency > availability)\nAP: Cassandra (availability > consistency)",["Distributed"],3,"","¿CAP?","En partition, elegir consistency o availability.")
    a("databases","Connection Pooling","Reutilizar conexiones a BD.","HikariCP, pgBouncer, SQLAlchemy pool.","from sqlalchemy import create_engine\nengine=create_engine('postgresql://...',pool_size=20)",["Performance"],2,"python","¿Por qué pooling?","Crear conexiones es costoso. Pool reutiliza.")
    a("databases","Query Plans","Plan de ejecución de consultas.","EXPLAIN ANALYZE muestra cómo ejecuta el motor.","EXPLAIN ANALYZE SELECT * FROM users u JOIN orders o ON u.id=o.user_id WHERE u.email='x';",["Performance"],2,"sql","¿Cómo leer EXPLAIN?","Seq Scan=malo. Index Scan=bueno. Cost rows width.")
    a("databases","Database Indexing Strategies","B-tree, Hash, GiST, GIN, BRIN.","Cada tipo para un caso de uso.","CREATE INDEX b ON t(col);  -- B-tree\nCREATE INDEX g ON t USING GIN(col);  -- GIN\nCREATE INDEX r ON t USING BRIN(col);  -- BRIN",["Optimization"],2,"sql","¿B-tree vs GIN vs BRIN?","B-tree rangos. GIN arrays/text. BRIN datos ordenados grandes.")
