    # AI/LLMS (30)
    a("ai","Supervised vs Unsupervised Learning","Dos paradigmas principales de ML.","Supervised: datos etiquetados. Unsupervised: sin etiquetas.","from sklearn.linear_model import LinearRegression\nm=LinearRegression()\nm.fit(X_train,y_train)",["ML fundamentals"],2,"python","¿Cuándo supervisado vs no supervisado?","Supervised con etiquetas. Unsupervised para descubrir patrones.")
    a("ai","Neural Networks Basics","Redes neuronales: capas, pesos, activaciones.","Neuronas con pesos, funciones de activación.","import torch.nn as nn\nclass Net(nn.Module):\n    def __init__(s):\n        super().__init__()\n        s.fc1=nn.Linear(784,128)\n        s.fc2=nn.Linear(128,10)\n    def forward(s,x):\n        return s.fc2(torch.relu(s.fc1(x)))",["Deep learning"],2,"python","¿Backpropagation?","Propagación del error hacia atrás para ajustar pesos.")
    a("ai","Gradient Descent","Optimización para minimizar pérdida.","Ajusta parámetros en dirección del gradiente negativo.","for ep in range(100):\n    pred=model(X)\n    loss=loss_fn(pred,y)\n    loss.backward()\n    opt.step()\n    opt.zero_grad()",["Optimization"],2,"python","¿Learning rate alto vs bajo?","Alto: rápido, puede divergir. Bajo: estable, puede atascarse.")
    a("ai","Overfitting vs Underfitting","Modelo demasiado complejo vs simple.","Overfitting memoriza training. Underfitting no aprende.","from sklearn.model_selection import cross_val_score\nscores=cross_val_score(model,X,y,cv=5)",["Model evaluation"],2,"python","¿Cómo prevenir overfitting?","Regularización, dropout, early stopping, más datos.")
    a("ai","Bias-Variance Tradeoff","Sesgo vs varianza en modelos.","Alto bias=underfitting. Alta varianza=overfitting.","from sklearn.model_selection import learning_curve\ntr,ts,tt=learning_curve(model,X,y,cv=5)",["Model selection"],3,"","¿Tradeoff?","Simples: alto bias, baja varianza. Complejos: al revés.")
    a("ai","Cross-Validation","Evaluar modelo en múltiples particiones.","K-fold: train en k-1, test en 1.","from sklearn.model_selection import KFold\nkf=KFold(n_splits=5,shuffle=True)\nscores=[]\nfor tr,te in kf.split(X):\n    m.fit(X[tr],y[tr])\n    scores.append(m.score(X[te],y[te]))",["Evaluation"],2,"python","¿vs train/test split?","CV más robusto, usa todos los datos.")
    a("ai","Feature Engineering","Transformar datos crudos en features.","Normalización, encoding, selección.","from sklearn.preprocessing import StandardScaler\nsc=StandardScaler()\nX=sc.fit_transform(X)",["Preprocessing"],2,"python","¿vs Deep Learning?","Feature engineering manual para ML clásico. DL aprende features automáticamente.")
    a("ai","Random Forest","Ensemble de árboles con bagging.","Múltiples árboles subsets aleatorios.","from sklearn.ensemble import RandomForestClassifier\nrf=RandomForestClassifier(n_estimators=100)\nrf.fit(X_train,y_train)",["Ensemble"],2,"python","¿vs Gradient Boosting?","RF paralelo, robusto. GB secuencial, más preciso.")
    a("ai","Gradient Boosting","Ensemble secuencial corrige errores anteriores.","XGBoost, LightGBM, CatBoost.","import xgboost as xgb\nm=xgb.XGBClassifier(n_estimators=100,lr=0.1)",["Ensemble","Competition"],2,"python","¿XGBoost vs LightGBM?","XGBoost más maduro. LightGBM más rápido con datos grandes.")
    a("ai","K-Means Clustering","Clustering particional en k grupos.","Basado en proximidad a centroides.","from sklearn.cluster import KMeans\nkm=KMeans(n_clusters=3)\nclusters=km.fit_predict(X)",["Clustering"],2,"python","¿Cómo elegir k?","Elbow method: inertia vs k. Silhouette score.")
    a("ai","PCA","Reducción de dimensionalidad preservando varianza.","Features correlacionadas en componentes no correlacionadas.","from sklearn.decomposition import PCA\npca=PCA(n_components=2)\nXr=pca.fit_transform(X)",["Dimensionality reduction"],2,"python","¿PCA vs t-SNE?","PCA lineal varianza global. t-SNE no lineal estructura local.")
    a("ai","Confusion Matrix","Tabla predicciones vs valores reales.","TP, TN, FP, FN para precision, recall, F1.","from sklearn.metrics import confusion_matrix\ncm=cm(y_test,y_pred)",["Evaluation"],2,"python","¿Precision vs recall?","Precision: positivos reales. Recall: reales detectados.")
    a("ai","ROC Curve","Tradeoff entre TPR y FPR.","AUC: área bajo curva. 0.5=random, 1.0=perfecto.","from sklearn.metrics import roc_curve,auc\nfpr,tpr,_=roc_curve(y_test,model.predict_proba(X_test)[:,1])\na=auc(fpr,tpr)",["Evaluation"],2,"python","¿Qué es AUC?","Capacidad de discriminación del modelo.")
    a("ai","Ensemble Methods","Combinar múltiples modelos.","Bagging, Boosting, Stacking, Voting.","from sklearn.ensemble import VotingClassifier\ne=VotingClassifier(estimators=[('rf',rf),('gb',gb)],voting='soft')",["Ensemble"],2,"python","¿Bagging vs Boosting?","Bagging reducir varianza. Boosting reducir bias.")
    a("llms","Transformer Architecture","Base de GPT, BERT, etc.","Self-attention paralelo para secuencias.","import torch.nn as nn\nclass TB(nn.Module):\n    def __init__(s,d,nh):\n        super().__init__()\n        s.att=nn.MultiheadAttention(d,nh)\n        s.ff=nn.Linear(d,d*4)",["NLP","Deep learning"],3,"python","¿Self-attention vs RNN?","Self-attention paralelo. RNN secuencial, olvida largo plazo.")
    a("llms","Tokenization","Dividir texto en tokens para LLMs.","BPE, WordPiece, SentencePiece.","from transformers import AutoTokenizer\nt=AutoTokenizer.from_pretrained('gpt2')\ntks=t.encode('Hello world')",["NLP"],2,"python","¿BPE vs WordPiece?","BPE merge frecuente. WordPiece máxima probabilidad. Ambos subword.")
    a("llms","Prompt Engineering","Diseñar prompts para mejores resultados.","Zero-shot, few-shot, chain-of-thought.","prompt='''Eres experto Python. Responde concisamente:\n¿Qué es un decorator?\nRespuesta:'''",["LLMs","Best practices"],1,"python","¿Zero-shot vs few-shot?","Zero-shot sin ejemplos. Few-shot con ejemplos.")
    a("llms","Fine-tuning","Entrenar LLM pre-entrenado en datos específicos.","Transfer learning para tareas específicas.","from transformers import AutoModelForCausalLM,Trainer\nm=AutoModelForCausalLM.from_pretrained('gpt2')\ntr=Trainer(model=m,train_dataset=ds,args=ta)\ntr.train()",["Transfer learning"],3,"python","¿vs prompt engineering?","Fine-tuning dominio específico. Prompt engineering uso general.")
    a("llms","RAG","Retrieval Augmented Generation.","Combinar LLMs con recuperación de documentos.","from langchain.vectorstores import FAISS\nvs=FAISS.from_documents(docs,emb)\nret=vs.as_retriever()\ndocs=ret.get_relevant_documents(q)",["RAG","LLMs"],2,"python","¿vs fine-tuning?","RAG datos cambiantes, reduce alucinaciones. Fine-tuning comportamiento específico.")
    a("llms","Vector Databases","Bases de datos para embeddings alta dimensión.","Pinecone, Weaviate, Milvus, pgvector.","from pgvector.sqlalchemy import Vector\nclass Doc(Base):\n    __tablename__='docs'\n    embedding=Column(Vector(1536))",["Embeddings","Search"],2,"python","¿Vector DB vs pgvector?","Vector DB dedicado más rápido para millones. pgvector suficiente para miles.")
    a("llms","Embeddings","Representaciones vectoriales de texto.","Capturan significado semántico.","from openai import OpenAI\nc=OpenAI()\nr=c.embeddings.create(input='¿Qué es Python?',model='text-embedding-3-small')\nemb=r.data[0].embedding",["Semantic search"],2,"python","¿Similitud coseno?","~1=mismo significado. ~0=no relacionados.")
    a("llms","Hallucinations","LLMs generan información falsa.","Sociedad por training data obsoleto.","r=c.chat.completions.create(model='gpt-4',\n    messages=[{'role':'user','content':'Población de Marte?'}],\n    temperature=0)",["LLM reliability"],2,"python","¿Reducir alucinaciones?","RAG con fuentes verificadas, temperature baja, chain-of-thought.")
    a("llms","Temperature and Top-p","Control de generación de LLMs.","Temperature aleatoriedad. Top-p diversidad.","r=c.chat.completions.create(model='gpt-4',\n    messages=[...],temp=0.2,top_p=0.9)",["Generation control"],2,"python","¿Alta vs baja?","Alta creativo. Baja preciso. 0=greedy.")
    a("llms","LLM Evaluation","Métricas de calidad de respuestas.","BLEU, ROUGE, perplexity, human eval.","from rouge_score import rouge_scorer\nsc=rouge_scorer.RougeScorer(['rougeL'])\ns=sc.score(ref,gen)",["Evaluation"],2,"python","¿BLEU vs ROUGE?","BLEU precision (traducción). ROUGE recall (resumen).")
    a("llms","Context Window","Límite de tokens que un LLM procesa.","GPT-4: 128k, Claude: 200k, Llama: 8k-128k.","from transformers import AutoTokenizer\nt=AutoTokenizer.from_pretrained('gpt2')\ntks=t.encode(text)\nif len(tks)>4096:text=t.decode(tks[:4096])",["LLM limits"],2,"python","¿Qué pasa si excedes?","Trunca texto o error. RAG ayuda con documentos largos.")
    a("llms","Chain-of-Thought","Razonamiento paso a paso en prompts.","Mejora razonamiento lógico y matemático.","prompt='''Resuelve paso a paso:\nSi un tren viaja 60km/h por 2.5h, ¿cuántos km?\n1. Velocidad=60\\n2. Tiempo=2.5\\n3. Distancia=60*2.5=150'''",["Reasoning"],1,"","¿CoT y tareas complejas?","Especialmente útil para matemáticas y lógica.")
    a("llms","LLM Safety","Asegurar comportamiento seguro y alineado.","RLHF, constitutional AI, guardrails.","r=c.chat.completions.create(model='gpt-4',\n    messages=[{'role':'user','content':'How to hack?'}])",["AI Safety"],2,"python","¿RLHF?","Reinforcement Learning from Human Feedback. Entrena con preferencias humanas.")
    a("ai_agents","ReAct Pattern","Reasoning + Acting.","El agente razona y ejecuta acciones.","prompt='''Eres un agente con herramientas.\nPregunta: ¿Clima en Madrid?\nPensamiento: Necesito buscar clima.\nAcción: search('clima Madrid')\nObservación: Soleado, 25°C\nRespuesta: Soleado, 25°C'''",["AI Agents"],2,"","¿vs chain-of-thought?","ReAct combina razonamiento con acciones externas.")
    a("ai_agents","Tool Use","LLMs usando herramientas externas.","Function calling para APIs, DB, código.","tools=[{'type':'function','function':{'name':'get_weather','parameters':{'type':'object','properties':{'city':{'type':'string'}}}}}]","Function calling",2,"python","¿Function calling vs code generation?","Function calling ejecuta funciones predefinidas. Code generation escribe código.")
    a("ai_agents","Memory in Agents","Recordar interacciones pasadas.","Short-term (conversación) y long-term (vector DB).","from langchain.memory import ConversationBufferMemory\nmem=ConversationBufferMemory()\nmem.save_context({'input':'Hi'},{'output':'Hello!'})",["Agent memory"],2,"python","¿Short vs long-term?","Short-term: conversación actual. Long-term: preferencias, historial.")
    a("ai_agents","Multi-Agent Systems","Múltiples agentes colaborando.","Cada agente rol especializado.","class Coord:\n    def coord(s,q):\n        r=s.res_agent.research(q)\n        return s.write_agent.write(r)",["Multi-agent"],3,"","¿vs single agent?","Multi-agent tareas complejas con especialización.")
    a("ai_agents","Agentic RAG","RAG con agentes decidiendo retrieval.","Decide si necesita retrieval o responde directo.","class ARAG:\n    def ans(s,q):\n        if s.needs_ret(q):\n            docs=s.ret.search(q)\n            return s.llm.gen(q,ctx=docs)\n        return s.llm.gen(q)",["Agentic","RAG"],3,"","¿RAG estático vs agentic?","Estático siempre recupera. Agestic decide dinámicamente.")
    a("prompt_engineering","Zero-Shot Prompting","Sin ejemplos en el prompt.","El modelo generaliza sin ejemplos previos.","prompt='''Clasifica:\\n\"Me encanta\" →'''",["Basic prompting"],1,"","¿Cuándo usarlo?","Cuando el modelo tiene conocimiento suficiente.")
    a("prompt_engineering","Few-Shot Prompting","2-5 ejemplos en el prompt.","Mejora significativamente rendimiento.","prompt='''Clasifica:\\n\"Me encanta\" → Positivo\\n\"Es terrible\" → Negativo\\n\"Es OK\" →'''",["In-context learning"],1,"","¿Cuántos ejemplos?","2-5 suelen ser suficientes.")
    a("prompt_engineering","Chain-of-Thought","Razonamiento paso a paso en prompts.","Mejora lógica y matemáticas.","prompt='''Paso a paso:\\n1. Velocidad=60\\n2. Tiempo=2.5\\n3. 60*2.5=150'''",["Reasoning"],1,"","¿CoT y tareas complejas?","Matemáticas, lógica, multi-step.")
    a("prompt_engineering","Role Prompting","Asignar rol o personalidad.","Mejora calidad y consistencia.","prompt='''Eres ingeniero senior con 15 años.\\nExplica microservicios a un junior.'''",["Persona"],1,"","¿Role y calidad?","Expertos producen respuestas más detalladas.")
    a("prompt_engineering","Structured Output","Formato específico de respuesta.","JSON, XML, tablas, listas.","prompt='''Extrae en JSON:\\n\"Juan tiene 30 años\"\\n{\\\"nombre\\\":\\\"\\\",\\\"edad\\\": }'''",["Structured data"],1,"","¿Structured output y parsing?","Útil para integrar respuestas en pipelines automatizados.")

    # TESTING (15)
    a("testing","Unit Testing","Verificar unidades individuales de código.","Aíslan componentes pequeños.","import pytest\ndef test_add():assert add(2,3)==5\ndef test_div():\n    assert divide(10,2)==5\n    with pytest.raises(ZeroDivisionError):divide(1,0)",["Test pyramid"],1,"python","¿Buen unit test?","Rápido, aislado, determinista, auto-verificable.")
    a("testing","Integration Testing","Componentes trabajan juntos.","Testing de interacciones.","def test_db():\n    db=create_test_db()\n    db.insert('users',{'name':'John'})\n    r=db.query('SELECT * FROM users')\n    assert len(r)==1",["Component interaction"],2,"python","¿vs unit?","Unit aislado rápido. Integration componentes reales.")
    a("testing","E2E Testing","Flujos completos de usuario.","Prueba completa desde perspectiva usuario.","from playwright.sync_api import sync_playwright\nwith sync_playwright() as p:\n    b=p.chromium.launch()\n    pg=b.new_page()\n    pg.goto('http://localhost:3000')\n    pg.fill('#email','test@mail.com')\n    pg.click('#submit')",["User flows"],3,"python","¿vs integration?","E2E toda la app, navegador real.")
    a("testing","Test-Driven Development","Tests antes del código.","Red→Green→Refactor.","def test_calc():\n    c=Calculator()\n    assert c.add(2,3)==5  # Red\n# Then write Calculator  # Green\n# Then refactor  # Refactor",["TDD"],2,"python","¿Beneficios?","Código testeable por diseño, confianza para refactorizar.")
    a("testing","Mocking","Objetos falsos para simular dependencias.","Aíslan dependencias externas.","from unittest.mock import Mock,patch\ndef test_api():\n    with patch('app.api.requests.get') as m:\n        m.return_value.json.return_value={'data':'test'}\n        assert fetch_data()=={'data':'test'}",["Isolation"],2,"python","¿Mock vs stub?","Mock verifica interacciones. Stub provee datos predefinidos.")
    a("testing","Test Coverage","Porcentaje de código cubierto por tests.","No es la única métrica de calidad.","# pytest --cov=app --cov-report=html\n# Target: core 90%+, critical 100%",["Quality metrics"],2,"","¿100% coverage y calidad?","No garantiza calidad. Cubre código ejecutado, no todos escenarios.")
    a("testing","Performance Testing","Miden rendimiento y carga.","Load, stress, soak testing.","from locust import HttpUser,task\nclass U(HttpUser):\n    @task\n    def idx(self):self.client.get('/')",["Load testing"],2,"python","¿Load vs stress?","Load volumen esperado. Stress más allá del límite.")
    a("testing","Security Testing","Identifican vulnerabilidades.","OWASP Top 10, injection, XSS.","def test_sql_inj():\n    r=client.get('/users?id=1; DROP TABLE users--')\n    assert r.status_code==400",["Security"],2,"python","¿OWASP Top 10?","A01 Access Control, A02 Crypto, A03 Injection...")
    a("testing","Contract Testing","Verifican acuerdos entre servicios.","API contracts: request/response schemas.","from pact import Consumer,Provider\ndef test_contract():\n    pact=Consumer('FE').has_pact_with(Provider('BE'))\n    pact.given('user exists').upon_receiving('get').with_request('GET','/users/1').will_respond_with(200,body={'id':1})",["Microservices"],3,"python","¿vs integration?","Contract verifica acuerdos entre equipos.")
    a("testing","Regression Testing","Cambios no rompen funcionalidad existente.","Se ejecutan después de cada cambio.","class Reg:\n    def test_crit(self):\n        assert login('u','p')==True\n        assert create_order({'item':'t'})is not None",["Stability"],1,"","¿Regression y CI/CD?","Automáticamente en cada PR para detectar regresiones.")
    a("testing","Visual Regression Testing","Detectan cambios visuales en UI.","Comparan screenshots.","from playwright.sync_api import sync_playwright\ndef test_vis():\n    with sync_playwright() as p:\n        b=p.chromium.launch()\n        pg=b.new_page()\n        pg.goto('http://localhost:3000')\n        pg.screenshot(path='current.png')",["UI testing"],3,"python","¿vs functional?","Visual detecta diseño. Functional verifica comportamiento.")
    a("testing","Chaos Engineering","Inyectar fallos para probar resiliencia.","Netflix Chaos Monkey.","import chaos_queue\nchaos_queue.inject_latency(5)\nassert get_response_time()<1000",["Resilience"],3,"python","¿En producción?","Sí, de forma controlada. Empezar en staging.")
    a("testing","Mutation Testing","Bugs intencionales para evaluar calidad de tests.","Si test no detecta mutant, es débil.","# mutants: cambiar operators, condicionales\n# Si tests pasan = test débil\n# Si tests fallan = test fuerte",["Test quality"],3,"","¿vs coverage?","Coverage mide código ejecutado. Mutation mide si tests realmente verifican.")
    a("testing","Property-Based Testing","Verifican propiedades en lugar de casos específicos.","Genera inputs aleatorios para encontrar edge cases.","from hypothesis import given,st as s\n@given(s.lists(s.integers()))\ndef test_sorted(l):assert sorted(l)==sorted(sorted(l))",["Generative testing"],3,"python","¿vs example-based?","Property-based encuentra edge cases automáticamente.")
    a("testing","Snapshot Testing","Guardar salida esperada y comparar.","Detecta cambios inesperados.","def test_config():\n    c=load_config()\n    assert c=={'debug':False,'port':8080}",["Regression"],1,"","¿y actualizaciones?","Cuando cambio es intencional, actualizar snapshot.")

    # ARCHITECTURE / DESIGN PATTERNS (15)
    a("design_patterns","Singleton","Una sola instancia global.","Config, pools.","class S:\n    _i=None\n    def __new__(c):\n        if c._i is None:c._i=super().__new__(c)\n        return c._i",["Config","Pools"],2,"python","¿Problemas?","Testing difícil, acoplamiento, viola SRP.")
    a("design_patterns","Factory","Delega creación de objetos.","Crear diferentes tipos sin especificar clase.","class AF:\n    @staticmethod\n    def create(t):\n        if t=='dog':return Dog()\n        elif t=='cat':return Cat()",["Creation"],2,"python","¿vs Abstract Factory?","Factory un tipo. Abstract Factory familias.")
    a("design_patterns","Observer","Dependencia uno-a-muchos.","Subject notifica observadores.","class Sub:\n    def __init__(s):s._o=[]\n    def attach(s,o):s._o.append(o)\n    def notify(s):\n        for o in s._o:o.upd(s)",["Events","Reactive"],2,"python","¿vs Pub/Sub?","Observer directo. Pub/Sub usa broker.")
    a("design_patterns","Strategy","Familia de algoritmos intercambiables.","Cambia algoritmo en runtime.","class Sorter:\n    def __init__(s,strat):s.strat=strat\n    def sort(s,d):return s.strat.sort(d)",["Algorithms"],2,"python","¿vs herencia?","Strategy cambia en runtime. Herencia estática.")
    a("design_patterns","Decorator Pattern","Añade responsabilidades envolviendo.","Alternativa a herencia.","class Coffee:\n    def cost(s):return 5\nclass Milk:\n    def __init__(s,c):s._c=c\n    def cost(s):return s._c.cost()+2",["Extension"],2,"python","¿vs Python decorators?","Pattern envuelve objetos. Python decorators modifican funciones.")
    a("design_patterns","Adapter","Convierte interfaz de una clase en otra.","Permite incompatibles trabajar juntas.","class Adapter:\n    def __init__(s,old):s.old=old\n    def convert(s):return f'Conv: {s.old.req()}'",["Integration"],2,"python","¿vs Facade?","Adapter traduce. Facade simplifica.")
    a("design_patterns","Facade","Interfaz simplificada a subsistema complejo.","Oculta complejidad.","class CompF:\n    def __init__(s):s.cpu=CPU();s.mem=Mem()\n    def start(s):s.cpu.freeze();s.mem.load()",["Simplificación"],2,"python","¿vs Adapter?","Facade crea nueva. Adapter traduce existente.")
    a("design_patterns","Repository","Abstrae acceso a datos.","Encapsula SQL, APIs.","class UR(ABC):\n    @abstractmethod\n    def get(s,id):pass",["Clean Arch"],2,"python","¿si hay ORM?","Desacoplamiento, testing, cambiar BBDD.")
    a("design_patterns","Dependency Injection","Objeto recibe dependencias de fuera.","Facilita testing.","class US:\n    def __init__(s,repo,email):s.repo=repo;s.email=email",["Testing"],2,"python","¿vs IoC?","IoC principio general. DI implementación.")
    a("design_patterns","CQRS","Separar lectura y escritura.","Escalabilidad independiente.","class CmdH:\n    def handle(s,cmd):s.repo.save(Order(cmd))\nclass QryH:\n    def get(s,id):return s.read_db.query(id)",["Scalability"],3,"","¿CQRS y microservicios?","Escalar reads y writes independientemente.")
    a("arch_clean","Clean Architecture","Separación en capas con dependencias dirigidas.","Domain→Use Cases→Adapters→Frameworks.","class US:\n    def __init__(s,repo):s.repo=repo  # Interface\n    def activate(s,id):\n        u=s.repo.get(id)\n        u.activate()",["Separation"],2,"python","¿y testing?","Fácil: mocks en boundaries, domain puro.")
    a("arch_hexagonal","Hexagonal Architecture","Puertos y adaptadores.","Core sin dependencias. Adaptadores conectan exterior.","class US:  # Port\n    def get(s,id):pass\nclass SQLA:  # Adapter\n    def get(s,id):return db.query(id)",["Adaptability"],3,"","¿vs Clean?","Hexagonal: puertos/adaptadores. Clean: capas. Ambos desacoplamiento.")
    a("arch_mvc","MVC","Model-View-Controller.","Separar responsabilidades web.","class User:  # Model\nclass UV:  # View\nclass UC:  # Controller\n    def __init__(s,m,v):s.m=m;s.v=v",["Web apps"],1,"","¿MVC y frameworks?","La mayoría de frameworks usan MVC o variaciones.")
    a("solid","SRP","Una clase, una razón para cambiar.","Single Responsibility Principle.","class US:\n    def get(s,id):pass  # Solo lectura\nclass ES:\n    def send(s,u,m):pass  # Solo email",["Maintainability"],1,"","¿SRP y testing?","Clases con SRP más fáciles de testear y mantener.")
    a("solid","OCP","Abierto para extensión, cerrado para modificación.","Agregar sin cambiar existente.","class PP:  # Open\n    def process(s,amt):pass\nclass PayPal(PP):  # Extension\n    def process(s,amt):pass",["Extension"],2,"","¿OCP en la práctica?","Interfaces, abstract classes, dependency injection.")

    # SOFT SKILLS / INTERVIEWS (30)
    a("soft_skills","Communication Skills","Comunicar ideas técnicas claramente.","Explicar a audiencias no técnicas.","BAD: 'Implementamos microservicio con K8s'\nGOOD: 'Dividimos la app en partes independientes que se despliegan por separado'","Team work",1,"","¿Cómo comunicar ideas?","Analogías, evita jerga, adapta al audiencia.")
    a("soft_skills","Problem Solving Framework","Enfoque estructurado para resolver.","Entender→Descomponer→Investigar→Implementar→Verificar.","1. Entender el problema\n2. Descomponer\n3. Investigar\n4. Implementar más simple\n5. Verificar con tests",["Analytical thinking"],1,"","¿Cómo abordar problema nuevo?","Entiende primero, planifica, implementa incrementalmente, verifica.")
    a("soft_skills","Code Review Best Practices","Dar y recibir feedback constructivo.","Constructivo, específico, educativo.","BAD: 'Esto está mal'\nGOOD: '¿Consideraste dict para O(1) lookup en lugar de lista O(n)?'",["Quality"],1,"","¿Code review efectivo?","Comenta código no persona. Sé específico. Sugiere mejoras.")
    a("soft_skills","Time Management","Gestionar tiempo y prioridades.","Eisenhower, time boxing, deep work.","Urgent+Important→Do\nImportant+Not urgent→Schedule\nUrgent+Not important→Delegate\nNot urgent+Not important→Eliminate",["Productivity"],1,"","¿Gestionar tiempo?","Time boxing, deep work, minimize context switching.")
    a("soft_skills","Technical Debt","Identificar y gestionar deuda técnica.","No toda es mala. Priorizar.","BAD: 'Debemos refactorizar todo'\nGOOD: 'Esta deuda nos cuesta 2h/semana. Arreglamos en próximo sprint.'",["Prioritization"],2,"","¿Cuándo abordar?","Cuando bloquea features, causa bugs frecuentes, o costo mantener > arreglar.")
    a("soft_skills","Mentoring Juniors","Guiar y desarrollar talento junior.","Escuchar, guiar, feedback constructivo.","1. Pregunta antes de dar respuesta\n2. Guía, no des la respuesta\n3. Anota patrones comunes\n4. Celebra mejoras",["Leadership"],2,"","¿Mentorar efectivamente?","Pregunta más que responder. Anota patrones. Celebra progreso.")
    a("soft_skills","Agile Methodologies","Scrum, Kanban, XP.","Scrum sprints. Kanban flujo continuo.","Scrum:\n- Sprint Planning\n- Daily Standup\n- Sprint Review\n- Retro",["Process"],1,"","¿Scrum vs Kanban?","Scrum sprints fijos. Kanban flujo continuo, límites WIP.")
    a("soft_skills","Conflict Resolution","Manejar desacuerdos técnicos productivamente.","Escuchar, datos, compromiso, decidir.","1. Escucha ambas partes\n2. Pide datos, no opiniones\n3. Compromiso o experimento\n4. Tech lead decide si no consenso",["Team dynamics"],2,"","¿Resolver conflictos?","Datos sobre opiniones. Experimentos controlados.")
    a("soft_skills","Technical Writing","Documentación clara y mantenible.","README, ADRs, runbooks.","## README:\n1. What is this?\n2. Quick start\n3. Configuration\n4. Architecture\n5. Contributing",["Documentation"],1,"","¿Documentación esencial?","README completo, ADRs para decisiones, runbooks para operaciones.")
    a("soft_skills","Negotiating Decisions","Persuadir al equipo sobre decisiones técnicas.","Datos, experimentos, trade-offs.","BAD: 'Deberíamos usar Redis'\nGOOD: 'Necesitamos caching para 10k RPM. Redis <1ms, PostgreSQL 50ms.'",["Persuasion"],2,"","¿Persuadir equipo?","Presenta datos, trade-offs, experimentos.")
    a("interview_prep","Behavioral Questions (STAR)","Preguntas conductuales con STAR.","Situation→Task→Action→Result.","Q: 'Tell me about failure'\nS: Deploy outage\nT: Restore service\nA: Rolled back, added canary\nR: Zero downtime since",["STAR method"],1,"","¿STAR method?","Ten 3-5 historias listas que muestren liderazgo, resolución, trabajo en equipo.")
    a("interview_prep","System Design","Diseñar sistemas escalables.","Requirements→High-level→Deep dive→Trade-offs.","1. Clarify (5 min)\n2. High-level (10 min)\n3. Deep dive (20 min)\n4. Trade-offs (5 min)",["Architecture"],3,"","¿Cómo abordar?","Clarifica requirements. High-level antes de deep dive. Trade-offs.")
    a("interview_prep","Coding Interview Tips","Consejos para entrevistas de código.","Clarify, think aloud, test, optimize.","1. Clarify\n2. Think aloud\n3. Code brute force\n4. Test examples\n5. Optimize",["Problem solving"],1,"","¿Brillar en interviews?","Clarifica, comunica razonamiento, empieza simple, optimiza después.")
    a("interview_prep","Portfolio Projects","Presentar proyectos efectivamente.","Problema→Solución→Resultado→Tecnologías.","### E-commerce API\n- Problem: scalable backend\n- Solution: FastAPI+PG+Redis\n- Result: 10k RPM, <100ms p95",["Presentation"],1,"","¿Presentar proyectos?","Enfócate en problema y resultado, no solo tecnologías.")
    a("interview_prep","Salary Negotiation","Estrategias para negociar compensación.","Investigar mercado, BATNA, paquete completo.","1. Research: Levels.fyi\n2. Know BATNA\n3. Negotiate total package\n4. Get offer in writing",["Negotiation"],2,"","¿Cómo negociar?","Investiga mercado, pide rango primero, paquete completo.")
    a("entrevistas","Data Structures Questions","Preguntas comunes de estructuras de datos.","Arrays, linked lists, trees, graphs, hash tables.","Q: ¿Linked list vs array?\nA: Inserciones/eliminaciones frecuentes O(1) en posición arbitraria.",["Arrays","Trees","Hash"],2,"","¿Más preguntadas?","Arrays (two pointers), Trees, Graphs (BFS/DFS), Hash tables.")
    a("entrevistas","Algorithm Complexity","Análisis de algoritmos.","Big-O, time/space trade-offs.","Q: ¿Amortized analysis?\nA: Costo promedio sobre secuencias de operaciones.",["Big-O"],2,"","¿Más preguntada?","O(n), O(n²), O(log n), O(n log n).")
    a("entrevistas","System Design Questions","Diseñar sistemas escalables.","URL shortener, chat, news feed.","Q: Diseña URL shortener\nA: Hash+redirect. DB key→URL. Cache Redis.",["Scalability"],3,"","¿Sistemas más preguntados?","URL shortener, chat, news feed, payment, search.")
    a("entrevistas","SQL Interview Questions","Preguntas comunes de SQL.","JOINs, GROUP BY, window functions.","Q: ¿N+1 query problem?\nA: 1 query para items + N para cada item. Resolver con JOINs.",["JOINs","Optimization"],2,"","¿Más preguntado?","JOINs, GROUP BY, subqueries, window functions.")
    a("entrevistas","Behavioral STAR","Preguntas conductuales STAR.","Tell me about a time when...","Q: Conflicto con compañero\nS: Disagree architecture\nT: Need decide before deadline\nA: Meeting, pros/cons, compromise\nR: Shipped on time",["STAR"],1,"","¿Comunes?","Failure, conflict, leadership, deadline, learning new tech.")
    a("habilidades","Technical Writing","Documentación técnica clara.","Claridad, concisión, estructura.","BAD: 'Configurar correctamente'\nGOOD: '1. Instala Docker\\n2. docker-compose up\\n3. localhost:3000'",["Documentation"],1,"","¿Efectiva?","Escribe para tu yo futuro. Pasos concretos. Ejemplos reales.")
    a("habilidades","Debugging Techniques","Encontrar y fixear bugs sistemáticamente.","Reproduce→Isolate→Hypothesize→Fix→Verify.","1. Reproduce\n2. Isolate\n3. Hypothesize\n4. Fix\n5. Verify",["Problem solving"],1,"","¿Cómo debugear?","Reproduce primero, aísla, hipótesis antes de codear, verifica.")
    a("habilidades","Learning New Technologies","Aprender nuevas tecnologías rápidamente.","Documentación→Tutorial→Proyecto→Contribuir.","1. Docs\n2. Tutorial\n3. Project\n4. Deep dive\n5. Contribute",["Continuous learning"],1,"","¿Aprender rápido?","Aprende haciendo. Un proyecto real enseña más que 10 tutoriales.")
    a("habilidades","Version Control Best Practices","Buenas prácticas con Git.","Commits semánticos, branching, PRs.","feat: add auth\nfix: resolve timeout\nrefactor: extract validation",["Git"],1,"","¿Commits semánticos?","feat/fix/refactor/docs/test/chore. Facilita changelog automático.")
    a("habilidades","API Design Principles","APIs RESTful limpias.","Consistencia, naming, versioning, errors.","GET /users/123\nPOST /users\nPUT /users/123\nDELETE /users/123\n{\"error\":\"Not found\",\"code\":404}",["REST"],2,"","¿Principios?","Consistencia, nouns plural, versioning, status codes, errors consistentes.")
    a("habilidades","Database Design","Diseño de bases de datos.","Normalización, indexes, relationships.","1NF: Atomic\n2NF: No partial\n3NF: No transitive\nCREATE INDEX idx ON users(email);",["Normalization"],2,"","¿Normalizar vs desnormalizar?","Normalizar integridad. Desnormalizar performance en reads.")
    a("habilidades","Microservices Communication","Patrones de comunicación.","Sync (REST, gRPC), Async (queues, events).","Sync: REST simple, gRPC performance\nAsync: RabbitMQ tasks, Kafka events\nSaga para transacciones distributed",["Microservices"],2,"","¿Sync vs async?","Sync simple response inmediata. Async resilient, scalable.")
    a("interfaces","Abstract Classes vs Interfaces","Diferencias y cuándo usar cada una.","Abstract: implementación parcial. Interface: solo contrato.","from abc import ABC,abstractmethod\nclass Shape(ABC):\n    @abstractmethod\n    def area(s):pass",["OOP"],2,"","¿Cuándo cada una?","Abstract: código compartido + contrato. Interface: contrato puro.")
    a("interfaces","Protocol Classes","Structural subtyping sin herencia.","Duck typing con type checking.","from typing import Protocol\nclass Comparable(Protocol):\n    def __lt__(s,o)->bool:...",["Type safety"],2,"python","¿vs ABC?","Protocol structural. ABC nominal.")
    a("css_moderno","CSS Grid","Layout bidimensional.","Filas y columnas simultáneamente",".grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}",["Layout"],1,"css","¿Grid vs Flexbox?","Grid bidimensional. Flexbox unidimensional.")
    a("css_moderno","CSS Flexbox","Layout unidimensional.","Un eje: fila o columna.",".flex{display:flex;justify-content:space-between;align-items:center}",["Layout"],1,"css","¿Flexbox y responsive?","Se adapta al contenido. Para 2D usar Grid.")
    a("css_moderno","CSS Custom Properties","Variables CSS nativas.","Reutilización y theming.",":root{--primary:#007bff;--spacing:16px}\n.btn{background:var(--primary);padding:var(--spacing)}",["Theming"],1,"css","¿vs SCSS?","CSS variables live en runtime. SCSS compile-time.")
    a("css_moderno","CSS Container Queries","Consultas basadas en container.","Componentes que se adaptan a su contenedor.", ".card-ct{container-type:inline-size}\n@container(min-width:400px){.card{display:grid;grid-template-columns:1fr 1fr}}",["Responsive"],2,"css","¿vs media queries?","Container queries: adaptar a container. Media queries: a viewport.")
    a("css_moderno","CSS :has() selector","Selector padre para CSS.","Seleccionar elementos padre basado en hijos.",".card:has(img){border:1px solid #ccc}\nli:has(>a[href])::marker{content:'→ '}",["Selectors"],2,"css","¿Selector padre?",".has() permite seleccionar padres. Antes imposible en CSS puro.")
    a("css_moderno","Subgrid","Grid que hereda tracks de su padre.","Alineación consistente entre padre e hijo.",".grid{display:grid;grid-template-columns:1fr 2fr;gap:16px}\n.child{display:grid;grid-template-columns:subgrid}",["Layout"],2,"css","¿Subgrid y alineación?","Los hijos heredan las columnas del padre para alineación perfecta.")

    # FRONTEND / MOBILE / GAME (20)
    a("react","React Hooks","State y lifecycle en componentes funcionales.","useState, useEffect, useRef.","function User({id}){\n  const[u,setU]=useState(null)\n  useEffect(()=>{fetchUser(id).then(setU)},[id])\n  return <div>{u?.name}</div>\n}",["State management"],2,"javascript","¿Reglas de hooks?","Solo en nivel superior. Solo en componentes/hooks. Empezar con 'use'.")
    a("react","React Memoization","Evitar re-renders innecesarios.","React.memo, useMemo, useCallback.","const Child=memo(({onClick,data})=>{\n  return<button onClick={onClick}>{data.length}</button>\n})\nconst handleClick=useCallback(()=>{},[])\nconst sorted=useMemo(()=>[...items].sort(),[items])",["Performance"],3,"javascript","¿useCallback vs useMemo?","useCallback para funciones props. useMemo para valores calculados.")
    a("react","React Context","Datos globales sin props drilling.","Provider en cima, consumidor en hijos.","const ThemeCtx=createContext()\nfunction ThemeProv({children}){\n  const[t,setT]=useState('dark')\n  return<ThemeCtx.Provider value={{t,setT}}>{children}</ThemeCtx.Provider>\n}",["Global state"],2,"javascript","¿Context vs Redux?","Context para datos que cambian poco. Redux para estado complejo.")
    a("vue","Vue.js Reactivity","Sistema de reactividad con proxies.","Detecta cambios automáticamente.","const state=reactive({count:0})\nconst doubled=computed(()=>state.count*2)\nfunction inc(){state.count++}",["Reactivity"],1,"javascript","¿Vue reactivity vs React?","Vue: automático con proxies. React: manual con setState.")
    a("vue","Vue Composition API","API para reutilizar lógica entre componentes.","setup(), ref, computed, watch.","function useCounter(){\n  const count=ref(0)\n  const doubled=computed(()=>count.value*2)\n  function inc(){count.value++}\n  return{count,doubled,inc}\n}",["Code reuse"],2,"javascript","¿vs Options API?","Composition API mejor para lógica compleja y reutilización.")
    a("angular","Angular Services","Servicios singleton para lógica de negocio.","Inyección de dependencias, providers.","@Injectable({providedIn:'root'})\nexport class UserService{\n  constructor(private http:HttpClient){}\n  getUsers(){return this.http.get('/api/users')}\n}",["DI","Services"],2,"typescript","¿Services y testing?","Services facilitan testing con DI y mocks.")
    a("svelte","Svelte Reactivity","Reactividad compilada, no runtime.","El compilador genera código eficiente.","<script>\n  let count=0\n  $: doubled=count*2  // Reactive\n  function inc(){count++}\n</script>\n<button on:click={inc}>{doubled}</button>",["Performance"],1,"javascript","¿Svelte vs React?","Svelte: compila, menos código, más rápido. React: más ecosistema.")
    a("astro","Astro Islands","Componentes interactivos en sitio estático.","Hydration selectiva para performance.","---\nimport React from 'react'\nimport Counter from '../components/Counter.jsx'\n---\n<html>\n  <Counter client:load />\n</html>",["Performance","SSG"],2,"javascript","¿Islands architecture?","HTML estático con componentes interactivos hidratados selectivamente.")
    a("nextjs","Next.js App Router","Routing basado en archivos con Server Components.","Rutas, layouts, loading states.","// app/page.tsx\nexport default function Home(){\n  return<div>Home</div>\n}\n// app/layout.tsx\nexport default function Root({children}){\n  return<html><body>{children}</body></html>\n}",["Routing","SSR"],2,"javascript","¿App Router vs Pages Router?","App Router: Server Components, layouts, streaming. Pages: más simple.")
    a("nuxt","Nuxt.js","Framework Vue para SSR/SSG.","Auto-imports, file-based routing.","// pages/index.vue\n<script setup>\nconst{data}=await useFetch('/api/users')\n</script>\n<template>\n  <div v-for=\"u in data\">{{u.name}}</div>\n</template>",["SSR","Vue"],2,"javascript","¿Nuxt vs Vue?","Nuxt: SSR/SSG automático. Vue: SPA manual.")
    a("fastapi","FastAPI","Framework web asíncrono de Python高性能.","Type hints, async/await, OpenAPI automático.","from fastapi import FastAPI\napp=FastAPI()\n@app.get('/users/{id}')\nasync def get_user(id:int):\n    return{'id':id}",["API","Async"],1,"python","¿FastAPI vs Flask/Django?","FastAPI: async, type hints, OpenAPI automático. Flask: simple. Django: full-stack.")
    a("django","Django","Framework web full-stack de Python.","ORM, admin, auth, template engine.","from django.db import models\nclass User(models.Model):\n    name=models.CharField(max_length=100)\n    email=models.EmailField(unique=True)",["Full-stack","ORM"],2,"python","¿Django vs Flask?","Django: batteries included. Flask: minimalista, flexible.")
    a("flask","Flask","Framework web micro de Python.","Minimalista, extensible.","from flask import Flask,jsonify\napp=Flask(__name__)\n@app.route('/api/users')\ndef users():\n    return jsonify([{'id':1,'name':'John'}])",["Micro framework"],1,"python","¿Flask vs FastAPI?","Flask: simple, síncrono. FastAPI: async, type hints, OpenAPI.")
    a("express","Express.js","Framework web minimalista para Node.js.","Middleware pattern, routing.","const express=require('express')\nconst app=express()\napp.get('/users/:id',(req,res)=>{\n  res.json({id:req.params.id})\n})",["Node.js","Middleware"],1,"javascript","¿Express vs Fastify?","Express: más popular. Fastify: más rápido, schema validation.")
    a("spring","Spring Boot","Framework Java para microservicios.","DI, AOP, security, data.","@RestController\npublic class UserController{\n    @Autowired\n    private UserService service;\n    @GetMapping(\"/users/{id}\")\n    public User getUser(@PathVariable Long id){\n        return service.getUser(id);\n    }\n}",["Java","Microservices"],2,"java","¿Spring Boot vs Quarkus?","Spring Boot: maduro, ecosistema. Quarkus: rápido startup, native.")
    a("dotnet","ASP.NET Core","Framework .NET para web APIs y apps.","高性能, DI, middleware.","[ApiController]\n[Route(\"api/[controller]\")]\npublic class UsersController:ControllerBase{\n    [HttpGet(\"{id}\")]\n    public ActionResult<User> GetUser(int id){\n        return Ok(new User{id=id});\n    }\n}",[".NET","API"],2,"csharp","¿ASP.NET Core vs Node.js?","ASP.NET: rendimiento, type safety, DI nativo. Node.js: JavaScript, async.")
    a("flutter","Flutter/Dart","Framework para apps móviles multiplataforma.","Widget tree, hot reload.","class MyApp extends StatelessWidget{\n  @override\n  Widget build(BuildContext context){\n    return MaterialApp(\n      home:Scaffold(\n        body:Center(child:Text('Hello')),\n      ),\n    );\n  }\n}",["Mobile","Cross-platform"],2,"dart","¿Flutter vs React Native?","Flutter: rendering propio, más consistente. React Native: JavaScript, bridge nativo.")
    a("react_native","React Native","Apps móviles con JavaScript/React.","Componentes nativos, hot reload.","import React from 'react'\nimport{View,Text}from'react-native'\n\nexport default function App(){\n  return<View><Text>Hello World</Text></View>\n}",["Mobile","React"],2,"javascript","¿vs Flutter?","React Native: JavaScript, bridge nativo. Flutter: Dart, rendering propio.")

    # C/C++/GO/RUST/JAVA (20)
    a("cpp","C++ Memory Management","new/delete, smart pointers, RAII.","RAII: Recursos se gestionan con lifetime de objetos.","auto p=std::make_unique<int>(42);  // Unique pointer\nauto s=std::make_shared<int>(42);  // Shared pointer\n// Se liberan automáticamente al salir scope",["RAII","Smart pointers"],3,"cpp","¿Smart pointers vs raw?","Smart pointers gestionan memoria automáticamente. Raw pointer riesgo de leak.")
    a("cpp","C++ Templates","Genéricos en tiempo de compilación.","Templates para código reutilizable con tipos diferentes.","template<typename T>\nT add(T a,T b){return a+b;}\n\nauto i=add(2,3);       // int\nauto d=add(2.5,3.1);   // double",["Generic programming"],3,"cpp","¿Templates vs inheritance?","Templates: compile-time polymorphism, zero overhead. Inheritance: runtime.")
    a("cpp","Move Semantics","Transferir ownership de recursos.","std::move para evitar copias innecesarias.","std::vector<int> v1={1,2,3};\nstd::vector<int> v2=std::move(v1);  // v1 está vacío ahora\n// v2 tiene los datos, sin copia",["Performance","Ownership"],3,"cpp","¿Move vs Copy?","Move transfiere ownership sin copiar. Copy duplica datos.")
    a("c","C Pointers","Acceso directo a memoria.","Fundamental en C para eficiencia.","int x=10;\nint *p=&x;\nprintf('%d',*p);  // 10\n*p=20;            // x ahora es 20",["Memory","Efficiency"],3,"c","¿Pointer arithmetic?","p+1 avanza sizeof(int) bytes. Permite navegar arrays eficientemente.")
    a("c","C Manual Memory Management","malloc/free para gestión de memoria.","Error-prone pero eficiente.","int *arr=malloc(100*sizeof(int));\nif(!arr){/* handle error */}\n// Use arr\nfree(arr);  // Must free!\n// arr is dangling now",["Memory","Systems programming"],3,"c","¿malloc vs calloc?","malloc asigna memoria sin inicializar. calloc asigna e inicializa a ceros.")
    a("csharp","C# LINQ","Language Integrated Query para colecciones.","Consultas elegantes sobre datos.","var result=users\n    .Where(u=>u.Age>25)\n    .OrderBy(u=>u.Name)\n    .Select(u=>u.Name)\n    .ToList();",["Data queries"],2,"csharp","¿LINQ vs SQL?","LINQ integra consultas en C# con type safety. SQL es para bases de datos.")
    a("csharp","C# Async/Await","Programación asíncrona en C#.","Task-based async pattern.","public async Task<User> GetUser(int id){\n    var resp=await httpClient.GetAsync($\"/api/users/{id}\");\n    return await resp.Content.ReadFromJsonAsync<User>();\n}",["Async"],2,"csharp","¿Task vs async/await?","async/await es syntactic sugar sobre Task. Más legible.")
    a("csharp","C# Dependency Injection","DI nativo en ASP.NET Core.","Configure services in Program.cs.","builder.Services.AddScoped<IUserService,UserService>();\n\n// In controller\n[ApiController]\npublic class UsersController(IUserService service){}",["ASP.NET Core"],2,"csharp","¿DI nativo vs externo?","ASP.NET Core tiene DI built-in. Más simple que usar contenedor externo.")
    a("rust","Rust Ownership","Sistema de ownership para memoria segura.","Sin garbage collector, sin data races.","fn main(){\n    let s1=String::from('hello');\n    let s2=s1;  // s1 ya no es válido\n    println!(\"{}\",s2);\n}",["Memory safety"],3,"rust","¿Ownership y borrowing?","Ownership: un dueño. Borrowing: referencias temporales. Sin data races en compile time.")
    a("rust","Rust Traits","Interfaces para polimorfismo.","Definen comportamiento compartido.","trait Drawable{\n    fn draw(&self);\n}\nimpl Drawable for Circle{\n    fn draw(&self){println!(\"○\")}\n}",["Polymorphism"],3,"rust","¿Traits vs interfaces?","Traits: composición de comportamiento, default implementations, zero-cost.")
    a("rust","Rust Error Handling","Result<T,E> y Option<T> para errores.","Sin excepciones, manejo explícito.","fn divide(a:f64,b:f64)->Result<f64,String>{\n    if b==0.0{Err(String::from(\"Division by zero\"))}\n    else{Ok(a/b)}\n}\nmatch divide(10.0,0.0){\n    Ok(v)=>println!(\"{}\",v),\n    Err(e)=>println!(\"Error: {}\",e),\n}",["Error handling"],3,"rust","¿Result vs exceptions?","Result: manejo explícito, no puede ignorarse. Exceptions: implícitas, pueden saltarse.")
    a("rust","Rust Concurrency","Fearless concurrency con ownership.","El compilador previene data races.","use std::thread;\nlet v=vec![1,2,3];\nlet handle=thread::spawn(move||{  // 'move' ownership\n    println!(\"{:?}\",v);\n});\nhandle.join().unwrap();",["Concurrency"],3,"rust","¿Fearless concurrency?","El sistema de ownership previene data races en compile time.")
    a("go","Go Goroutines","Concurrencia ligera en Go.","Miles de goroutines con poco overhead.","go func(){\n    fmt.Println(\"Hello from goroutine\")\n}()\n\n// Channels for communication\nch:=make(chan int)\ngo func(){ch<-42}()\nfmt.Println(<-ch)",["Concurrency"],2,"go","¿Goroutines vs threads?","Goroutines: ~2KB stack, gestiona Go runtime. Threads: ~1MB, OS managed.")
    a("go","Go Channels","Comunicación entre goroutines.","Canales tipizados para enviar/recibir datos.","ch:=make(chan int,10)  // Buffered\ngo func(){ch<-42}()\nval:=<-ch\n\n// Select for multiple channels\nselect{\ncase v:=<-ch1:\n    process(v)\ncase v:=<-ch2:\n    process(v)\ndefault:\n    // No ready\n}",["Communication"],2,"go","¿Buffered vs unbuffered?","Buffered: tamaño fijo, no bloquea hasta lleno. Unbuffered: sincronización directa.")
    a("go","Go Interfaces","Interfaces implícitas.","Duck typing: si tiene los métodos, implementa.","type Writer interface{\n    Write([]byte)(int,error)\n}\n\n// Any type with Write method implements Writer\n// No need for 'implements' keyword",["Polymorphism"],2,"go","¿Interfaces implícitas vs explícitas?","Implícitas: desacoplamiento, más flexible. Explícitas: más explícito, menos flexible.")
    a("java","Java Streams API","Procesamiento funcional de colecciones.","Operaciones encadenadas sobre datos.","List<String> result=users.stream()\n    .filter(u->u.getAge()>25)\n    .map(User::getName)\n    .sorted()\n    .collect(Collectors.toList());",["Functional programming"],2,"java","¿Streams vs loops?","Streams: declarativo, paralelizable, chainable. Loops: imperativo, más control.")
    a("java","Java Spring DI","Inyección de dependencias con Spring.","@Autowired, @Component, @Service.","@Service\npublic class UserService{\n    @Autowired\n    private UserRepository repo;\n    \n    public User getUser(Long id){return repo.findById(id);}\n}",["Spring","DI"],2,"java","¿Spring DI vs constructor?","Constructor injection: explícito, testeable. @Autowired: implícito, menos verbose.")
