def main():
    concepts = build()
    OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(OUTPUT_PATH, 'w', encoding='utf-8') as f:
        json.dump({"meta":{"generated":True,"count":len(concepts)},"concepts":concepts}, f, indent=2, ensure_ascii=False)
    print(f"Generated {len(concepts)} concepts → {OUTPUT_PATH}")

    # Stats
    cats = {}
    for c in concepts:
        cat = c['cat']
        cats[cat] = cats.get(cat, 0) + 1
    print(f"Categories: {len(cats)}")
    for cat, count in sorted(cats.items(), key=lambda x: -x[1])[:20]:
        print(f"  {cat}: {count}")

if __name__ == "__main__":
    main()
